  },
  families = {
    ["air-elementals"] = { title = "Elementales de aire", note = { { "Los remolinos de polvo cruzan los campos abiertos, mientras torbellinos mayores cobran forma en Desolace y Silithus. Es más fácil ver a un elemental de aire por lo que reúne a su alrededor: polvo, nubes y las cosas sueltas que el viajero creía bien guardadas." }, { "El Martillo Crepuscular invoca poderes elementales en el desierto del sur. Una tormenta allí puede tener algo más detrás que un tiempo revuelto. El viento ha adquirido una forma y quizá alguien lo haya invitado." } } },
    ["bandits-and-mercenaries"] = { title = "Bandidos y mercenarios", note = { { "Un cartel de busca y captura hace que un forajido parezca un problema solitario. Los campamentos Deambulador de Tanaris y el recinto de Kurzen en Vega de Tuercespina sugieren otra cosa: guardias, suministros y una organización que sobrevive a la pérdida de cualquier bandido concreto." }, { "Los seguidores de Kurzen fueron soldados antes de que la selva se apoderara de su expedición. Otros trabajan por dinero o acechan los caminos. Sus motivos varían y quizá falten los estandartes, pero un campamento vigilado tiene mucho en común con el ejército al que perteneció." } } },
    ["basilisks"] = { title = "Basiliscos", note = { { "Un basilisco puede pasar por un tramo de roca rota hasta que se mueve. Su cuerpo bajo y su piel gruesa encajan en las colinas secas de Vega de Tuercespina y en los desiertos del sur. Los cristales de algunos ejemplares viejos hacen que el parecido resulte bastante convincente." }, { "La dificultad está en la mirada. Estos lagartos pueden dejar a un adversario vivo rígido como una piedra, de modo que la costumbre del naturalista de acercarse a mirar se vuelve una negociación incómoda. Hay mucho que admirar en un basilisco, siempre que mire hacia otro lado." } } },
    ["bats"] = { title = "Murciélagos", note = { { "Una cueva que parece vacía de día puede tener el techo lleno de murciélagos. Los murciumbríos sobrevuelan los caminos de Claros de Tirisfal, mientras los pasajes espinosos de Rajacieno albergan sus propias colonias. Unas alas ocupan una parte sorprendente de un túnel estrecho." }, { "Los murciélagos de la peste de las tierras orientales pertenecen a un relato menos alegre. Llevan enfermedades por un país ya arruinado por la Plaga. La silueta del murciélago es familiar. Lo que transporta depende mucho de dónde haya pasado el día." } } },
    ["bears"] = { title = "Osos", note = { { "Desde los osos negros de Khaz Modan hasta los blancos Dentoesquirla de Cuna del Invierno, los osos hacen que un bosque parezca bien habitado aunque apenas se vea nada más. Un lomo ancho entre los árboles, una zarpa pesada en el sendero, y de pronto la maleza parece menos vacía." }, { "Su fuerza les ha dado un lugar en las artes druídicas y en los relatos de los cazadores. Para el oso, sin embargo, los asuntos inmediatos son otros: comida, territorio y lo que acaba de acercarse demasiado. Es perfectamente posible admirarlo sin entrar a formar parte de esos asuntos." } } },
    ["birds"] = { title = "Aves de las alturas", note = { { "Al alzar la vista en un paso de montaña, las alas pueden pertenecer a un hipogrifo, un dracoleón o un grifo. Los viajeros suelen poner a los tres en la misma categoría. Las astas, las colas con aguijón y los picos ganchudos sugieren que el naturalista debería esforzarse un poco más." }, { "Los hipogrifos llevan jinetes elfos de la noche, los grifos son compañeros habituales de los Martillo Salvaje y la Horda tiene sus jinetes del viento. Más allá de los nidos y las pajareras, sus parientes salvajes llenan el mismo cielo. Colocar una silla en cualquier criatura que puede irse volando sin más ya es un logro considerable." } } },
    ["black-dragonflight"] = { title = "El Vuelo Negro", note = { { "Los dragonantes negros habitan tierras marcadas por el fuego y la piedra rota. Hay crías en Montañas Crestagrana y Tierras Inhóspitas. Sus servidores mayores guardan la fortaleza de Nefarian en la Cumbre de Roca Negra y la guarida de Onyxia en Marjal Revolcafango." }, { "La traición de Alamuerte pesa sobre el Vuelo, mientras sus hijos persiguen ambiciones propias. Los experimentos de Nefarian reúnen a dragones de distintos colores en una misma labor terrible. El naturalista acostumbrado a describir las diferencias entre Vuelos encuentra poco consuelo en lo que Nefarian intenta hacer con ellos." } } },
    ["blackrock"] = { title = "El clan Roca Negra", note = { { "Los orcos Roca Negra dominan los caminos que rodean su montaña y las salas de su interior. Desde Las Estepas Ardientes, sus asaltantes llegan a Montañas Crestagrana, donde Fuerte de Petravista recuerda constantemente a los habitantes de Villa del Lago la fuerza del clan." }, { "Desgarro Puño Negro reclama el título de Jefe de Guerra, aunque sus seguidores sirven bajo las alas de Nefarian. Llevan las armas y ambiciones de la vieja Horda a un mundo en el que Thrall intenta construir otra. La diferencia se aprecia mucho antes de llegar a la Cumbre." } } },
    ["blighted-elementals"] = { title = "Elementales corrompidos", note = { { "Los pozos de alquitrán de Un'Goro y el suelo envenenado de Frondavil producen formas que se mueven. No por resultar ambos desagradables al tacto deben recibir la misma historia. Las bestias de alquitrán pertenecen al cráter. Los horrores tóxicos, a un bosque herido." }, { "Los residuos de Gnomeregan y la peste de las Tierras de la Peste añaden otros ejemplos a esta página problemática. Cada uno lleva algo del lugar que lo formó. Sus diferencias importan: lo que surge del suelo puede contar al naturalista qué le ha ocurrido al propio terreno." } } },
    ["blue-dragonflight"] = { title = "El Vuelo Azul", note = { { "Los dragonantes azules guardan lugares arcanos: las ruinas antiguas de Azshara y las salas heladas de Mazthoril. El Vuelo de Malygos lleva mucho tiempo a cargo de la magia, lo que coloca desde el principio en una posición incómoda al mortal que rebusca entre semejantes tesoros." }, { "Azuregos vigila Azshara con una actitud muy personal hacia los visitantes. Sus tratos sobre un viejo libro de contabilidad mágico revelan sentido del humor. Un deber antiguo no le ha impedido divertirse con los recados de un aventurero." } } },
    ["boars"] = { title = "Jabalíes", note = { { "Los jabalíes aparecen con la misma facilidad en las barrancas rojas de Durotar que en los campos verdes de Elwynn. Cambia el color, y el jabalí de risco lleva un buen abrigo contra la nieve, pero los colmillos dibujan la misma silueta inconfundible." }, { "Los Dentosangre de Páramos de Poniente molestan a las granjas y proporcionan carne útil. Esto deja al jabalí en la desdichada posición de ser requerido fuera del campo y dentro de una olla, a menudo por la misma persona. Suele oponerse a ambas cosas." } } },
    ["bronze-dragonflight"] = { title = "El Vuelo Bronce", note = { { "Las Cavernas del Tiempo se abren bajo Tanaris, aunque los asuntos del Vuelo Bronce van mucho más allá de ese tramo de desierto. Los dragones de Nozdormu guardan el tiempo mismo, una tarea para la que la Liga no dispone de instrumentos de medida satisfactorios." }, { "Su participación en el sellado de Ahn'Qiraj pertenece a la historia documentada. Anacronos aún vigila el desierto desde fuera de las cavernas, inmenso testigo vivo de una guerra cuyos demás rastros yacen bajo la arena." } } },
    ["burning-blade"] = { title = "El Filo Ardiente", note = { { "El nombre del Filo Ardiente sigue en boca de brujos y adoradores de demonios. Sus sectarios ocupan cuevas en Durotar y se reúnen en Desolace. Bajo Orgrimmar, Sima Ígnea acerca esa lealtad de manera incómoda al nuevo hogar de la Horda." }, { "El pueblo de Thrall ha luchado por escapar del dominio de la Legión. Estos sectarios invitan de vuelta a sus servidores, con círculos de invocación en las mismas tierras donde se han asentado los orcos libres. Para un pueblo que recupera una forma de vida más antigua, son vecinos especialmente amargos." } } },
    ["burning-legion"] = { title = "La Legión Ardiente", note = { { "La presencia de la Legión cambia el paisaje. En Frondavil, los árboles llevan el daño. En Las Tierras Devastadas, los demonios ocupan el terreno en torno al Portal Oscuro. El Aquelarre Mannoroc y el Barranco del Demonio conservan sus propios recuerdos de la invasión." }, { "Sus filas son muy distintas: un manáfago caza magia, un infernal trae piedra y llamas, y un diablillo puede causar una cantidad notable de problemas en muy poco espacio. Las guerras que los trajeron han terminado, pero el mapa de sus campamentos restantes dista mucho de estar vacío." } } },
    ["carrion-birds"] = { title = "Aves carroñeras", note = { { "Las aves carroñeras son las pacientes: buitres, zopilotes y cóndores que giran sobre Los Baldíos, Tierras Inhóspitas y Las Mil Agujas, esperando que la tierra mate por ellos. Los Desgarradores de Páramos de Poniente se han vuelto más atrevidos desde que las granjas se vaciaron y no siempre esperan." }, { "Son una señal que conviene interpretar. Un círculo de estas aves en el cielo indica que algo ha muerto debajo o está a punto de hacerlo. A veces es prudente averiguar qué antes de acercarse." }, { "Los rocs del lejano sur son otra cosa: enormes aves de presa que cazan animales vivos y consideran al viajero uno más." } } },
    ["centaurs"] = { title = "Centauros", note = { { "Los clanes centauros ocupan el campo abierto de Kalimdor, con aldeas y bandas de guerra repartidas por Los Baldíos, Desolace y Las Mil Agujas. Los tauren los conocen como perseguidores desde hace generaciones. En Desolace, los nombres Gelkis, Magram y Maraudine indican dominios rivales además de campamentos distintos." }, { "Un viajero puede negociar con algunos clanes, aunque la amistad con uno suele costar la de otro. Sus chamanes hablan de la tierra, y Theradras tiene adoradores entre ellos. Aquí hay más que una incursión vista desde el camino." }, { "Su ascendencia lleva hasta Theradras y Zaetar, el hijo de Cenarius al que mataron sus propios hijos. Maraudon conserva esa historia familiar de una forma particularmente desdichada." } } },
    ["chimaeras"] = { title = "Quimeras", note = { { "Dos cabezas en un cuerpo alado hacen inconfundible a una quimera, incluso antes de que alcance su aliento. Los elfos de la noche han luchado junto a estas criaturas, cuya fuerza y ataque corrosivo resultan temibles contra la piedra y la carne por igual." }, { "En Cuna del Invierno vive una variedad pálida y lanuda adaptada a la nieve. Frente a Feralas, la Isla del Terror alberga a los enormes quimeroks. En el mapa es una isla pequeña. Un quimerok da motivos de sobra para calcular cuánto terreno queda entre la bestia y la costa." } } },
    ["crabs"] = { title = "Cangrejos", note = { { "Un cangrejo lleva una pequeña fortaleza por la orilla. El caparazón sostiene casi todo el argumento, las pinzas resuelven el resto y el conjunto se desplaza de lado con una seguridad admirable." }, { "Los reptadores de arena y de oleaje ocupan playas de ambos continentes. Los cocineros aprecian su carne, mientras una extensión de arena tranquila ofrece al naturalista algo digno de observar: una criatura ocupada en sus asuntos en el límite entre la tierra y el mar. No todo lo que hay en una playa espera un barco." } } },
    ["crocolisks"] = { title = "Crocoliscos", note = { { "Los crocoliscos son criaturas antiguas, de mandíbulas largas y cuerpo acorazado, que han sobrevivido a imperios por el sencillo procedimiento de quedarse inmóviles en agua cálida y comer lo que se acerque a beber. Habitan los lagos de Khaz Modan, los pantanos de Los Humedales, los ríos de Vega de Tuercespina y las orillas de Marjal Revolcafango." }, { "Un crocolisco en la ribera parece dormido. No lo está. Puede cubrir la distancia hasta un viajero descuidado más deprisa de lo que parece decente para algo tan pesado." }, { "Su piel da buen cuero y su carne sabe mejor de lo que cabría esperar. Ninguna de las dos merece perder una pierna." } } },
    ["cult-of-the-damned"] = { title = "El Culto de los Malditos", note = { { "Entre los muertos de la Plaga hay personas que aún viven. El Culto de los Malditos proporciona nigromantes, acólitos y manos voluntarias a un ejército que, de otro modo, tendría que fabricar a todos sus reclutas." }, { "Scholomance, bajo Castel Darrow, da a esas artes una escuela cuyas lecciones transcurren entre los restos de Lordaeron. En otros lugares, el culto atiende calderas de peste y levanta a los caídos. Un erudito vivo ante un escritorio debería tranquilizar. Aquí la materia de estudio marca toda la diferencia." } } },
    ["dark-iron-dwarves"] = { title = "Enanos Hierro Negro", note = { { "El trabajo de los Hierro Negro es inconfundiblemente enano: minas profundas, fortificaciones pesadas y máquinas construidas para durar más que sus fabricantes. La fortaleza del clan bajo la Montaña Roca Negra es también una ciudad, con forjas, una arena y la corte de un emperador." }, { "La Guerra de los Tres Martillos los dejó enfrentados a Forjaz. La invocación de Thaurissan los dejó sometidos a Ragnaros. Ahora sus agentes trabajan mucho más allá de la montaña, en canteras y campamentos de todo Khaz Modan." }, { "La pólvora y la buena mampostería son cosas familiares en manos de otro enano. Lo que complica esta página es hacia dónde apunta el cañón." } } },
    ["defias"] = { title = "La Hermandad Defias", note = { { "Una máscara roja puede significar un carterista en un camino de Elwynn o un artesano que trabaja bajo Minas de la Muerte. La Hermandad Defias nació del trabajo impagado de los canteros que reconstruyeron Ventormenta. Edwin VanCleef llevó ese agravio a Páramos de Poniente." }, { "Ahora las granjas sufren por una disputa que sus dueños no resolvieron. Bajo Arroyo de la Luna, la Hermandad ha organizado algo mucho mayor que los robos de camino: talleres, matones contratados y un barco. La destreza de los canteros ha sobrevivido. La ciudad a la que iba a servir se ha convertido en su objetivo." } } },
    ["dragonmaw"] = { title = "El clan Faucedraco", note = { { "Los Faucedraco llevaron dragones rojos a la guerra al mantener cautiva a Alexstrasza en Grim Batol. La libertad de la reina rompió ese poder, pero el clan aún tiene campamentos en Los Humedales, donde sus estandartes son un peligro conocido junto a los caminos." }, { "Sus incursiones pertenecen a las guerras residuales de la vieja Horda. Ahora el propio Grim Batol está vigilado por el Vuelo Rojo, recordatorio imponente de que el clan tuvo una prisionera mucho mayor que cualquiera que sus guerreros restantes puedan capturar." } } },
    ["druids-of-the-fang"] = { title = "Los druidas del Colmillo", note = { { "Naralex entró en Cuevas de los Lamentos con la esperanza de restaurar Los Baldíos mediante el Sueño Esmeralda. Sigue dormido allí, y la pesadilla que lo atrapó ha cambiado tanto a las bestias de la caverna como a sus discípulos." }, { "Los Druidas del Colmillo llevan nombres de serpiente y adoptan su forma: Cobrahn, Anacondra, Pythas y Serpentis. Sus ritos ocupan las cuevas que debían ser el comienzo de una tierra más verde. Bajo Los Baldíos abundan el agua y la vegetación. El problema es lo que ha crecido con ellas." } } },
    ["earth-elementals"] = { title = "Elementales de tierra", note = { { "Los elementales de tierra traen consigo la ladera: pesadas formas de roca que se mueven por Tierras Inhóspitas, cuerpos de obsidiana en las tierras calcinadas de Roca Negra. La diferencia entre una roca y un habitante puede ser breve." }, { "Uldaman también alberga vigilantes de piedra, construcciones que guardan un lugar hecho por alguien en vez de espíritus salvajes que recorren terreno abierto. Para la Liga la diferencia es considerable. Un elemental de roca puede ser parte del paisaje. Un guardián de piedra es prueba de que alguien tenía algo que proteger." } } },
    ["earthen"] = { title = "Los terráneos", note = { { "Los terráneos son seres de piedra viva, creados por los titanes para dar forma a las profundidades del mundo. Algunos aún recorren las salas de la cámara de los titanes en Uldaman, cumpliendo el cometido para el que fueron creados." }, { "Los discos de platino de esa cámara dicen que los enanos descendemos de ellos. En el sentido más literal, son mis antepasados, e intentarán matarte." }, { "Los registro con un respeto que no acabo de explicar y una cautela que sí puedo." } } },
    ["faerie-dragons"] = { title = "Dragones feéricos", note = { { "Un dragón feérico lleva alas brillantes y un cuerpo pequeño y veloz a los bosques antiguos de Kalimdor. Pese al nombre y a su lugar en esta página, no es un miembro diminuto de uno de los grandes Vuelos." }, { "Estas criaturas tienen vínculos con el Sueño Esmeralda y una relación peculiar con la magia. Los elfos de la noche las conocen como aliadas del bosque. La variedad descarriada de Cuevas de los Lamentos pertenece a un entorno mucho menos afortunado. El color por sí solo dice poco de lo que le ha ocurrido allí a una criatura." } } },
    ["fire-elementals"] = { title = "Elementales de fuego", note = { { "La llama viva camina por las tierras quemadas de la Montaña Roca Negra y las laderas del volcán de Un'Goro. Un elemental de fuego da al movimiento familiar de un incendio una dirección y una voluntad propias." }, { "Ragnaros gobierna los fuegos más profundos bajo Roca Negra, con servidores por todo su dominio. En otros lugares, chamanes e invocadores llaman a las llamas. El elemento sigue siendo reconocible, aunque su sola presencia no dice a quién obedece, si es que obedece a alguien." } } },
    ["forest-trolls"] = { title = "Trols de bosque", note = { { "Los Secacorteza, Vilrama y Fustamusgo ocupan bosques cubiertos de restos del antiguo dominio trol. Jintha'Alor sigue siendo una formidable ciudad templo, con terrazas que suben por Tierras del Interior en vez de hundirse discretamente en el terreno." }, { "Los Amani combatían contra Quel'Thalas mucho antes de que se formaran los reinos humanos actuales. Aquella rivalidad perdura entre tribus de fortuna muy distinta. Los Sañadiente comercian con la Horda en la costa de Tierras del Interior, mientras sus vecinos mantienen sus dominios en el interior." }, { "La piel verde y los colmillos permiten reconocer a un trol de bosque. No le dicen al viajero qué recibimiento le espera." } } },
    ["furbolgs"] = { title = "Fúrbolgs", note = { { "Las aldeas fúrbolg pertenecen a los bosques antiguos de Kalimdor. Los tótems, refugios y chamanes les dan un lugar entre sus pueblos, aunque un viajero que llegue a un campamento corrompido quizá solo vea violencia." }, { "Los Tuercepinos, Bosque Negro, Muertobosque y Nevada han sufrido cambios terribles. Los Fauces de Madera han resistido ese destino y aún guardan los túneles entre Frondavil, Claro de la Luna y Cuna del Invierno. Les sobran motivos para desconfiar de los extraños." }, { client = "forever", "El Bastión Faucenegra de Azshara pertenece a otra tribu. La corrupción también ha arraigado allí. Los Fauces de Madera de Frondavil no deben cargar con la culpa de lo que hay tras aquella puerta de piedra." } } },
    ["giants"] = { title = "Gigantes", note = { { "Los gigantes marinos recorren las costas de Kalimdor y los grandes caminantes de los acantilados ocupan las alturas de Azshara y Feralas. Ante un cabo distante es difícil juzgar su tamaño. Un árbol o una columna derruida a su lado dan la medida que faltaba." }, { "Los relatos vinculan a los gigantes del mundo con su antigua formación. La Liga aún tiene mucho que establecer sobre las distintas clases. Para un topógrafo, hasta sus huellas son accidentes importantes del terreno, y un ejemplar vivo puede interrumpir una vista muy amplia." } } },
    ["gnolls"] = { title = "Gnolls", note = { { "Los campamentos gnoll se agrupan junto a minas, campos y caminos mal vigilados. Las tiendas Zarparrío de Elwynn y Páramos de Poniente, las chozas Pellejomusgo de Los Humedales y los campamentos Zarpaleña de Feralas comparten una ventaja práctica: las provisiones ajenas quedan al alcance." }, { "Sus manadas tienen líderes, lanzadores de hechizos y asaltantes, y pueden someter a un poblado a una presión real. La reputación de Hogger ha llegado mucho más allá de su rincón de Elwynn. Es una distinción poco habitual para un gnoll, aunque quienes pagan su recompensa agradecerían ponerle fin." } } },
    ["goblins"] = { title = "Goblins", note = { { "Los goblins registrados aquí se encuentran al otro lado de un taller o de un campo de batalla, no de un mostrador. VanCleef tiene ingenieros en Minas de la Muerte, y aparecen inventos peligrosos dondequiera que sus fabricantes hallan sitio para trabajar." }, { "Una trituradora o un guardia contratado dicen algo de los recursos detrás de un pequeño campamento goblin. Buena parte del combate puede recaer en algo que el ingeniero ha construido, comprado o convencido para ponerse delante. La estatura del inventor mide mal el tamaño de la empresa." } } },
    ["gorillas"] = { title = "Gorilas", note = { { "Los gorilas de Vega de Tuercespina, Feralas y Un'Goro tienen tamaño suficiente para destacar en una selva abarrotada. Los Lomoblanco, los simios Velobrumoso y los grandes Tronadores varían de tamaño, pero hasta los pequeños hacen que los troncos parezcan delgados." }, { "Sus nombres dicen algo de la impresión que dejan: Rey Mukla, Uhk'loc, U'cha. Los cazadores buscan una bestia concreta y vuelven con un nombre que suena al de un gobernante. Un gorila no necesita corona ni trono para ocupar un claro por completo." } } },
    ["great-cats"] = { title = "Grandes felinos", note = { { "Los grandes felinos aportan buena parte del silencio de un bosque. El pelaje oscuro de un sable de la noche desaparece entre los árboles de Teldrassil, un sable de hielo pertenece a las nieves de Cuna del Invierno y una pantera de Vega de Tuercespina puede resultar difícil de distinguir incluso a plena luz del día." }, { "El vínculo de los elfos de la noche con sus sables muestra otra cara de estos cazadores: compañeros y monturas además de depredadores. Fuera de los animales adiestrados, la misma gracia sirve para cazar. Un tigre que cruza un sendero soleado es una hermosa visión, por poco que dure." } } },
    ["great-saurians"] = { title = "Demosaurios y bestias de Un'Goro", note = { { "Un'Goro tiene espacio para criaturas que harían parecer estrechos casi todos los demás bosques. Los demosaurios sobresalen por encima de la maleza, los estegodones llevan grandes placas en el lomo y los pterrordáctilos giran sobre el borde del cráter. Un diemetradón junto a las aguas termales puede parecer casi modesto en semejante compañía." }, { "La expedición de Marshal ha dado a estas bestias nombres y un lugar en sus informes. El cráter les proporciona el resto: vegetación densa, suelo humeante y espacio para que un demosaurio desaparezca tras el siguiente grupo de árboles. Levantar su mapa es una tarea considerable." } } },
    ["green-dragonflight"] = { title = "El Vuelo Verde", note = { { "El Vuelo Verde de Ysera protege el Sueño Esmeralda, pero la Pesadilla ha alcanzado a algunos de sus propios guardianes. Los dragonantes de los grandes portales de Vallefresno, Feralas, Tierras del Interior y Bosque del Ocaso hacen visible ese peligro en el mundo despierto." }, { "La sombra de Eranikus ronda el Templo Sumergido, y otros dragones poderosos han salido cambiados del Sueño. Los grandes árboles en torno a los portales siguen siendo hermosos. Eso contribuye a lo inquietante de la corrupción: la entrada a un lugar de vida ha adquirido guardianes tan atormentados." } } },
    ["grimtotem"] = { title = "Los Tótem Siniestro", note = { { "Los campamentos Tótem Siniestro ocupan posiciones dominantes: la Cumbre de la Nube Negra sobre Las Mil Agujas, un recinto en Feralas y otras posesiones por Kalimdor. Sus guerreros y chamanes tienen la fuerza de los demás tauren, dirigida contra vecinos que a menudo comparten sus antepasados." }, { "Magatha Tótem Siniestro tiene un lugar entre los ancianos de Cima del Trueno, aunque las ambiciones de su tribu la enfrentan al rumbo de Cairne. Los tótems y tiendas familiares pueden hacer que un campamento hostil parezca, engañosamente, un refugio del camino." } } },
    ["harpies"] = { title = "Arpías", note = { { "Las arpías anidan sobre los accesos a los poblados ajenos. Los nidos Viento Seco de Durotar, las alturas Viento Furioso de Mulgore y los nidos Alabruja de Los Baldíos dan a las alas ventaja sobre una caravana." }, { "Sus garras solo son parte del peligro. Las brujas de la tormenta añaden hechizos al chillido de una bandada alterada. Es difícil llegar con preguntas a un nido alto en un acantilado. Por eso buena parte de lo que sabe la Liga de las arpías se ha recogido desde el suelo." } } },
    ["hostile-elves"] = { title = "Elfos hostiles", note = { { "Una expedición élfica entre las ruinas puede buscar lo mismo que la Liga: una inscripción, una reliquia, una pieza superviviente de artesanía antigua. En Azshara, la búsqueda de poder arcano perdido de los elfos de sangre hace que ese interés común garantice poco recibimiento." }, { "La Masacre tiene sus propios estudiosos peligrosos de la magia, entre ellos Lethtendris. Las ciudades antiguas aún contienen poder que merece buscarse, y quienes llegan hasta él no siempre dejan sitio para un segundo erudito." } } },
    ["hydras"] = { title = "Hidras", note = { { "Una hidra se anuncia con varias cabezas a la vez. Los cuellos largos emergen del agua costera o de una poza subterránea, y cuesta decidir qué par de ojos merece atención primero." }, { "Las Brumazote rondan las costas de Kalimdor, mientras otras hidras viven en las profundidades de Maraudon. Gahz'rilla tiene un estanque sagrado en Zul'Farrak y el culto de los Furiarena. Casi todas las criaturas de este libro deben conformarse con un lugar donde alimentarse. Esa ha conseguido una congregación." } } },
    ["hyenas"] = { title = "Hienas", note = { { "Las hienas encajan en las tierras secas: siluetas enjutas contra el polvo de Los Baldíos, Tanaris y Desolace. Sus llamadas delatan a la manada incluso cuando la hierba o un pliegue del terreno la ocultan." }, { "Los nombres que reciben rara vez son cariñosos. Risadiente, Patapústula, hiena famélica: el viajero recuerda el sonido, los dientes o el estado de la bestia que lo siguió. En ese último nombre cabe toda una vida difícil, allí donde nunca está asegurada la próxima comida." } } },
    ["ice-trolls"] = { title = "Trols de hielo", note = { { "Los Peloescarcha conocen Dun Morogh como su hogar, no como un camino hacia Forjaz. Su fortaleza al oeste de Kharanos y sus campamentos en la nieve siguen cerca de los poblados enanos que los han expulsado de buena parte del valle." }, { "Rebanacabezas, videntes y taumaturgos umbríos defienden lo que aún poseen. Para un enano joven suelen ser los primeros enemigos trols. Para los Peloescarcha, el enano es otro recién llegado de la ciudad de arriba. El mismo paso nevado lleva dos relatos muy distintos de a quién le pertenece." } } },
    ["insects"] = { title = "Insectos", note = { { "No todo insecto grande pertenece a una colmena silítida. Escarabajos y otros coleópteros habitan por su cuenta los desiertos y las ruinas antiguas, aunque su tamaño a veces hace que un viajero alcance el arma antes que el cuaderno." }, { "En Zul'Farrak, los escarabajos se mueven entre las construcciones y tumbas de los Furiarena. Contra el muro de un templo parecen un detalle menor. Reunidos a los pies de uno exigen bastante más atención." } } },
    ["jungle-trolls"] = { title = "Trols de selva", note = { { "Las ruinas trols de Vega de Tuercespina son historia habitada. Las tribus Cabellesangre y Machacacráneos luchan entre las piedras antiguas, mientras Zul'Gurub sigue siendo un centro del poder Gurubashi. Sus sumos sacerdotes han traído de vuelta a Hakkar al mundo." }, { "Los Atal'ai llevan también el culto al dios de la sangre al Templo Sumergido. Otros trols de selva han seguido otro rumbo: los Lanza Negra pertenecen a la Horda de Thrall, y la Isla Yojamba alberga el esfuerzo de Zandalar contra Hakkar. Un viejo imperio ha dejado muchos herederos, con propósitos muy distintos." } } },
    ["kobolds"] = { title = "Kóbolds", note = { { "Una luz en una mina abandonada suele pertenecer a un kóbold. Sus velas marcan los túneles de Elwynn y Páramos de Poniente, donde los pasajes estrechos permiten que un pequeño excavador se convierta en una gran molestia." }, { "La conocida protesta, \"¡Tú no quitar vela!\", deja bastante claro el asunto más urgente. Más allá de eso, la vela cuenta algo práctico: alguien pretende trabajar y vivir en la oscuridad. Para el minero que vuelve a su concesión, el túnel está ocupado. Para el kóbold, el minero es un intruso." } } },
    ["kodos"] = { title = "Kodos", note = { { "Las manadas de kodos dan a las llanuras abiertas un ritmo lento y pesado. Los tauren viajan y luchan junto a estas grandes bestias, y un kodo cargado es una visión habitual donde la Horda tiene mucho camino por delante." }, { "Desolace alberga una reunión más extraña: el Cementerio de Kodos, donde los animales viejos vienen a morir entre los huesos de los suyos. Las manadas vivas impresionan, pero esos restos inmensos dan otra medida de ellas. Una criatura tan ligada a las caravanas en marcha puede dejar tras de sí un lugar muy quieto." } } },
    ["leper-gnomes"] = { title = "Gnomos parias", note = { { "La caída de Gnomeregan no envió a todos los supervivientes a Forjaz. La radiación cambió el cuerpo y la mente de algunos que quedaron dentro, y los gnomos parias aún habitan sus accesos y salas llenas de máquinas." }, { "La piel verde hace visible el daño de inmediato. La ropa y las herramientas gnómicas familiares hacen más difícil apartar su significado. Para los exiliados, la antigua ciudad contiene vecinos además de las cosas que los expulsaron." } } },
    ["living-plants"] = { title = "Plantas vivas y ancianos", note = { { "Un bosque puede moverse sin brisa. Los antárboles y ancianos dan a los bosques élficos sus grandes formas caminantes, mientras los azotadores y las trepadoras ocupan un terreno mucho más cercano a las botas del viajero." }, { "Algunos defienden un bosque vivo. Otros han cambiado por la corrupción. Los brezomadera de Teldrassil y la vegetación de La Masacre merecen relatos distintos, aunque ambos dificulten cruzar un sendero." }, { "El pantano tiene sus propias formas de vegetación y barro en movimiento. Las raíces, las ramas y un verde familiar son solo el principio de identificar lo que ha surgido de él." } } },
    ["lost-ones"] = { title = "Los Perdidos", note = { { "Los draenei del Puerto son refugiados de Draenor, el mundo del que llegaron los orcos. Los Perdidos del Retiro Fangoso comparten ese origen, aunque su aislamiento violento oculta la relación a quien cruza el pantano." }, { "Magtoor y sus compañeros ayudan donde pueden, entre personas que apenas saben qué pensar de ellos. Su presencia da un contexto más triste al campamento de los Perdidos: otro pueblo disperso lejos de casa, con algunos de los suyos ya incapaces de hallar refugio entre los demás." } } },
    ["machines"] = { title = "Gólems y máquinas", note = { { "Un gólem de la cosecha en los campos de Páramos de Poniente pertenece a otra clase de naturaleza. Las trituradoras de Sierra Espolón, las máquinas de guerra de Gnomeregan y las construcciones de los Hierro Negro comenzaron en un taller, sea cual sea el destino que hayan tenido sus instrucciones." }, { "Las intenciones del fabricante pueden sobrevivir en el diseño: brazos cortantes, garras de cosecha, un cañón donde un animal tendría la cabeza. La máquina no necesita explicarse. A menudo se puede leer su propósito en las herramientas que lleva incorporadas." } } },
    ["makrura"] = { title = "Makrura", note = { { "Los makrura ocupan los bajíos de Kalimdor con una presencia muy distinta a la de los cangrejos vecinos. Los cuerpos erguidos, las pinzas prensiles y las colonias vigiladas pertenecen a un pueblo, por extrañas que resulten su lengua y su figura." }, { "La costa de Durotar ofrece a muchos orcos jóvenes su primer encuentro con ellos. Más al sur hay colonias mayores. La playa ofrece poca cobertura a quien se acerca desde tierra, mientras el agua a la espalda de un poblado makrura no tiene por qué ser el límite de sus habitantes." } } },
    ["murlocs"] = { title = "Múrlocs", note = { { "Las aldeas múrloc dejan una marca reconocible en la costa: chozas bajas, redes de pesca y mucho ruido cuando se acerca un extraño. Sus herramientas y poblados merecen más atención de la que suelen recibir en los relatos de una carga gorgoteante." }, { "Defienden esas aldeas juntos, lo que explica que una pelea con uno pueda extenderse tan deprisa por la playa. A la mayoría de los viajeros les cuesta entender su habla. Eso es una dificultad de traducción, no una prueba de que no digan nada." } } },
    ["naga"] = { title = "Naga", note = { { "Los naga ocupan lugares sumergidos que antes formaban parte del mundo de los elfos de la noche: La Ensenada de Zoram, las ruinas de Azshara y la costa de Costa Oscura. Sus cuerpos serpentinos se adaptan ahora a las aguas que cubrieron el antiguo dominio de los Altonato." }, { "Salieron a la luz tras la Tercera Guerra y desde entonces se han establecido en muchas costas. Las brujas del mar y los mirmidones armados hacen que sean algo más que campamentos playeros dispersos. Entre las columnas rotas, parecen haber regresado a una ciudad cuyas calles solo ellos pueden seguir usando." } } },
    ["oddities"] = { title = "Criaturas extrañas", note = { { "Algunos encuentros hacen que los encabezados de una historia natural parezcan insuficientes. Un monstruo singular, un habitante extraño de una mazmorra o una criatura venerada por un culto local pueden carecer de parientes útiles en el resto del libro." }, { "Esta página conserva el encuentro concreto mientras su lugar en el relato general sigue sin aclararse. En un diario de campo hay espacio para una pregunta sin respuesta, sobre todo si acaba de salir caminando de un lago." } } },
    ["ogres"] = { title = "Ogros", note = { { "Los ogros atravesaron el Portal Oscuro con la Horda y luego se dispersaron en clanes por Azeroth. Una torre arruinada o una cueva de montaña pueden albergar ahora a los Puño de Roca, Aplastacresta, Rotapolvo u otro clan cuyo nombre se haya convertido en advertencia local." }, { "Su tamaño es lo primero que se ve, pero los magos ogros dan poco apoyo a las bromas habituales sobre su inteligencia. Dos cabezas pueden tener un dominio formidable de la magia." }, { "Los Quebrantarrocas de Marjal Revolcafango se han unido a la Horda. En otros lugares hay que averiguar la lealtad de cada clan por separado. Una silueta conocida no sirve de presentación." } } },
    ["oozes"] = { title = "Mocos y babosas", note = { { "Un moco ofrece muy poca forma con la que describirlo. El color y la consistencia deben hacer buena parte del trabajo: los lodos de un pantano, los extraños restos del desastre de Gnomeregan, la suciedad que se mueve en aguas envenenadas." }, { "Algunos dejan restos de lo que han tragado, un registro poco apetecible pero útil de su entorno. Es fácil pasarlos por alto junto a una gran bestia o un árbol que camina. Una mancha de baba que avanza cuesta arriba tiene su propio derecho a entrar en el cuaderno." } } },
    ["other-beasts"] = { title = "Otras bestias", note = { { "Hay bestias para las que un encabezado familiar bien ordenado prometería más de lo que permiten las pruebas. Una forma inusual, un ejemplar solitario o una criatura conocida sobre todo por el nombre de un encargo de caza pueden encontrar aquí su lugar." }, { "Un catálogo amplio es útil hasta que esconde al animal en sus categorías. Estos registros dejan espacio para el individuo: dónde se encontró, qué aspecto tenía y qué lo distingue del último monstruo supuestamente único." } } },
    ["other-dragonkin"] = { title = "Otros dragonantes", note = { { "El color de un dragón suele ofrecer un comienzo para su historia. Ayuda menos ante un ejemplar desconocido o los dragonantes mezclados que producen los experimentos de Nefarian en la Cumbre de Roca Negra." }, { "Estas criaturas se registran aquí hasta que haya motivos sólidos para situarlas en otro lugar. Un catálogo ordenado no debería ocultar una identificación difícil, sobre todo cuando la criatura es bastante grande para protestar por la demora." } } },
    ["other-elementals"] = { title = "Otros elementales", note = { { "Las divisiones habituales entre tierra, aire, fuego y agua no resuelven todos los encuentros. Algunos seres animados y formas elementales inusuales llegan a esta página sin un lugar claro entre los demás." }, { "Su entorno suele ofrecer el mejor comienzo: la cámara de un invocador, una sala antigua o un tramo extraño de campo abierto. El registro puede conservar esos detalles aunque la naturaleza de su habitante siga sin aclararse." } } },
    ["other-peoples"] = { title = "Otros humanoides", note = { { "Conviene registrar a algunos enemigos por el lugar y la compañía en que se encontraron. Un forajido solitario, el guardia de una mazmorra y un mago renegado pueden compartir raza sin compartir causa." }, { "Estas páginas conservan sus encuentros sin inventarles un estandarte. Un nombre, un arma y un campamento son comienzos modestos para un relato, pero resultan mejores que dejar que una persona desconocida desaparezca en la palabra \"enemigo\"." } } },
    ["other-undead"] = { title = "Otros no-muertos", note = { { "La peste de Lordaeron no explica todos los cadáveres que caminan. En Bosque del Ocaso hay tumbas alteradas por otras manos, y una maldición antigua o el trabajo de un nigromante pueden mover a los muertos lejos de los ejércitos de la Plaga." }, { "Aquí un nombre puede ser especialmente valioso. Los restos quizá hayan durado más que la explicación, mientras el registro de un pueblo o un pariente superviviente aún la conserva. La criatura del cementerio y la persona del relato son a veces el mismo sujeto, visto desde extremos opuestos de una historia." } } },
    ["owls"] = { title = "Búhos", note = { { "A menudo resulta más fácil encontrar un búho por los ojos. Los estrígidos de Teldrassil reposan en un bosque ya lleno de vigilancia élfica, mientras los grandes búhos de Cuna del Invierno destacan pálidos contra los árboles oscuros." }, { "Los Picoferro de Frondavil pertenecen a un bosque dañado y comparten sus peligros. En otros lugares queda tiempo para apreciar la quietud de un ave posada antes de que abra las alas. Los bosques ya tienen ruido de sobra. Un búho ofrece un excelente estudio de su ausencia." } } },
    ["pirates"] = { title = "Piratas", note = { { "Un campamento pirata tiene mucho de puerto: barcos, almacenes y marineros con trabajo. La diferencia se aprecia cuando un navío Velasangre se acerca a Bahía del Botín o las tripulaciones de los Mares del Sur reclaman otro cargamento." }, { "Sus refugios salpican las costas cálidas, desde la Costa Mercante hasta Tanaris. El comercio goblin ha llenado esas aguas de tráfico suficiente para mantener tanto a los mercaderes como a quienes los roban. Desde un cabo lejano, las velas pueden parecerse mucho." } } },
    ["quilboar"] = { title = "Jabaespines", note = { { "Las espinas inmensas de Los Baldíos son el hogar de los jabaespines. Sus tradiciones nombran a Agamaggan como antepasado, y la presencia del semidiós caído pertenece a la tierra tanto como a sus ritos." }, { "Los campamentos Crines de Acero, Lomopelo y Rajacieno defienden ese país de los tauren, los centauros y la nueva Horda. Sus chamanes dan a los poblados espinosos otra clase de fuerza. En Zahúrda Rajacieno, los tratos con la Plaga han llevado a la tribu Caramuerte a una lealtad más oscura." }, { "El forastero ve una pared de zarzas. Detrás hay hogares, tribus rivales y una historia más antigua que el camino que pasa junto a ella." } } },
    ["rams-and-goats"] = { title = "Carneros y cabras", note = { { "Un carnero parece completamente a gusto en terrenos que hacen que un enano se pregunte por la calidad de sus botas. La lana espesa y los cuernos curvos son habituales en todo Khaz Modan, y las monturas que salen de Forjaz tienen parientes salvajes en las mismas montañas." }, { "Los Pico Tormenta también recurren a los carneros en el Valle de Alterac. Entre un sendero de montaña y un campo de batalla hay bastantes exigencias para las patas de una montura. El carnero afronta ambas cosas con expresión de haber dado ya el terreno por bueno." } } },
    ["raptors"] = { title = "Raptores", note = { { "Un raptor es patas traseras, cola y dientes, construido de manera muy distinta a un lobo o un felino. Los Garrasangre de Durotar y los Solescama de Los Baldíos son ejemplos conocidos. Las variedades mayores cazan en Los Humedales y las selvas del sur." }, { "Los jinetes trols han hecho de ellos compañeros, una costumbre que exige mucha confianza en el animal que se lleva a la espalda. En libertad, la estrecha silueta de un raptor puede perderse entre los juncos hasta que se vuelve. La cabeza suele ser lo primero que recuerda el viajero." } } },
    ["red-dragonflight"] = { title = "El Vuelo Rojo", note = { { "Las crías rojas aún habitan Los Humedales, donde los miembros mayores del Vuelo de Alexstrasza guardan Grim Batol. La montaña mantuvo cautiva a su reina bajo el dominio de los orcos Faucedraco, que emplearon a sus hijos en la Segunda Guerra." }, { "Su liberación puso fin al cautiverio sin convertir Grim Batol en un lugar acogedor. Ahora los dragonantes rojos guardan sus accesos contra los extraños. Para un Vuelo encargado de proteger la vida, esas puertas vigiladas conservan un recuerdo largo y amargo." } } },
    ["restless-spirits"] = { title = "Fantasmas y espíritus sin descanso", note = { { "No todos los fantasmas de Azeroth sirven a la Plaga. Algunos son espíritus que nunca encontraron reposo: los Altonato que rondan sus torres arruinadas en Costa Oscura y Azshara, los ahogados y los asesinados, los guerreros que cayeron lejos de su hogar y siguen vagando." }, { "Algunos solo están tristes. Otros están furiosos y esa furia es todo lo que queda de ellos. Unos pocos hablarán, si escuchas." }, { "La Liga los registra con cuidado. Al fin y al cabo, son los testigos más antiguos que tenemos." } } },
    ["sand-trolls"] = { title = "Trols de arena", note = { { "Zul'Farrak aún se alza sobre la arena como una ciudad, pese a la ruina que la rodea. Los Furiarena defienden sus terrazas y estanques sagrados de un desierto cada vez más lleno de goblins, bandidos y aventureros." }, { "Allí se adora a Gahz'rilla, y las tumbas tienen guardianes que no permanecieron muertos. Es un mal lugar para tratar cada piedra vieja como una reliquia abandonada. Los descendientes de sus constructores son perfectamente capaces de discutir el derecho de un visitante a llevársela." } } },
    ["satyrs"] = { title = "Sátiros", note = { { "Un campamento de sátiros es una herida en un bosque antiguo. Figuras cornudas se mueven entre árboles enfermos, y los elfos de la noche que se enfrentan a ellas luchan contra criaturas cuya historia comenzó entre su propio pueblo." }, { "Xavius, consejero de la reina Azshara, fue el primero de los sátiros, transformado por Sargeras durante la guerra antigua. Los suyos siguen sirviendo a la corrupción en Vallefresno y Frondavil. Han pasado diez mil años, pero el bosque aún pierde terreno en torno a sus campamentos." } } },
    ["scarlet-crusade"] = { title = "La Cruzada Escarlata", note = { { "Los estandartes rojos de la Cruzada Escarlata marcan algunas de las posiciones humanas supervivientes más fuertes de Lordaeron: el monasterio, Vega del Amparo, Mano de Tyr y parte de Stratholme. Sacerdotes, paladines y soldados defienden esos muros de los no-muertos." }, { "Sus sospechas llegan mucho más allá de la Plaga. Pueden tratar a los extraños como portadores de peste o enemigos disfrazados, y los Renegados no tienen lugar en su idea de un reino restaurado. Es posible encontrar defensores vivos tras las barricadas sin encontrar refugio." } } },
    ["scorpids"] = { title = "Escórpidos", note = { { "Los escórpidos aprovechan notablemente bien el suelo seco. Sus caparazones bajos se confunden con la tierra roja de Durotar y el polvo de los desiertos del sur. La cola alzada se distingue un instante después, con cierta inquietud." }, { "Su veneno y su armadura tienen usos, lo que envía a jóvenes cazadores en busca de criaturas contra las que sus mayores los habían prevenido. Los orcos de Durotar conocen bien los caparazones de escórpido. Un ejemplar dispuesto para el estudio es una hermosa armadura natural, con articulaciones que merecen observarse de cerca." } } },
    ["scourge"] = { title = "La Plaga", note = { { "La Plaga convierte una población en un ejército: esqueletos, necrófagos, víctimas de la peste y abominaciones cosidas llenan los caminos y las ruinas de Lordaeron. Sus nigromantes añaden soldados dondequiera que encuentren cuerpos." }, { "Scholomance y Stratholme son grandes centros de esa labor, mientras Zahúrda Rajacieno muestra hasta dónde llega su influencia. Los muertos no necesitan cosechas ni descanso, y las tierras que ocupan pierden poco a poco la vida que antes las sostenía." }, { "Entre los huesos y las ropas arruinadas quedan restos de habitantes corrientes. El ejército no necesita sus antiguos oficios, pero un diario de campo aún puede reconocerlos." } } },
    ["servants-of-the-firelord"] = { title = "Servidores del Señor del Fuego", note = { { "Los despiertallamas del Núcleo de Magma son servidores inconfundibles de Ragnaros: figuras armadas de cuerpo inferior serpentino, a gusto entre los fuegos bajo la Montaña Roca Negra. Lucifron, Gehennas, Shazzrah y los suyos guardan los accesos al Señor del Fuego." }, { "Aquí el calor de la montaña forma parte de un reino habitado. Lo que un enano consideraría un lugar imposible para construir contiene guardias, comandantes y el asiento de un señor. La falta de suelo cómodo es un problema exclusivo del visitante." } } },
    ["shadow-council"] = { title = "El Consejo de la Sombra", note = { { "El Consejo de la Sombra ayudó a atar a la vieja Horda a la Legión. Su influencia superviviente aparece ahora en lugares como Jaedenar, donde sectarios y demonios ocupan el mismo terreno corrompido." }, { "La Horda de Thrall ha rechazado a esos amos, pero los círculos de invocación siguen ahí. En torno a ellos se reúnen practicantes de varios pueblos, entregados a artes cuyo coste ya está escrito por todo Frondavil. Los árboles ennegrecidos son un acompañamiento útil para cualquier promesa que se haga dentro del campamento." } } },
    ["sharks-and-fish"] = { title = "Tiburones y peces", note = { { "La superficie de un lago dice muy poco de sus habitantes. Loch Modan tiene sus dementes. Las costas tienen trilladores y tiburones lo bastante grandes como para agradecer especialmente la vista desde un barco." }, { "Estos son los peces que el pescador encuentra a una distancia poco conveniente. Una aleta en aguas abiertas es solo un fragmento de la criatura que hay debajo, y un banco puede convertir una poza tranquila en un movimiento repentino. El libro de la vida bajo la superficie es extenso. Esta página cubre sus pasajes con más dientes." } } },
    ["silithid"] = { title = "Silítidos y qiraji", note = { { "Las colmenas silítidas cambian la forma de los desiertos del sur. Los montículos se alzan sobre túneles ocupados por avispas, obreros y grandes atracadores acorazados. La superficie solo ofrece una parte de la población que hay debajo." }, { "Los qiraji de Ahn'Qiraj mandan sobre estos enjambres. Hace mil años, la Guerra del Mar de Dunas terminó cuando los elfos de la noche y los dragones sellaron sus ejércitos tras el Muro del Escarabajo." }, { "Las colmenas de este lado del muro convierten aquella guerra en una preocupación presente. Un montículo bajo en el horizonte puede señalar una ocupación mucho mayor bajo la arena." } } },
    ["snakes"] = { title = "Serpientes", note = { { "Una serpiente puede ocupar muy poco de la atención de un viajero hasta que cruza el sendero. Enroscada, su cuerpo apenas revela su longitud. Una cabeza alzada basta para reclamar un pequeño trozo de suelo por completo." }, { "Las serpientes de Cuevas de los Lamentos han cambiado por la pesadilla que hay allí. En Zul'Gurub tienen un lugar en el culto al dios de la sangre. Ambos escenarios dan al naturalista algo más que considerar que las escamas y el veneno, aunque estos siguen siendo temas suficientes." } } },
    ["spiders"] = { title = "Arañas", note = { { "Las telarañas dividen una cueva entre el espacio que un viajero ve y el que ya está ocupado. En las minas de Elwynn y en el Tejemadera de Teldrassil, las propias arañas suelen ser tan grandes que explican por qué un camino conocido ha quedado en silencio." }, { "Los sacos de veneno y la seda atraen a boticarios y artesanos. La seda es un material especialmente fino para encontrar tendido en una puerta abandonada. Su fabricante no necesita telar ni le interesan los usos que se darán al trabajo terminado." } } },
    ["stags-and-steeds"] = { title = "Ciervos, caballos y herbívoros", note = { { "Las zhebras y jirafas forman parte de las amplias vistas de Los Baldíos, mientras los ciervos de Vallefresno aparecen entre troncos viejos. Sus siluetas distintas ayudan a leer el país antes que cualquier poste indicador." }, { "Los cazadores aprecian su carne y sus pieles, pero Ogtinc, en Azshara, tiene otro interés en los corceles Pezuñamusgo. Ve el espíritu de un animal seguro en sus astas intactas y pide un par perfecto. Esa corona imponente es también el medio de defensa del corcel, lo que dificulta obtener un ejemplar entero." } } },
    ["syndicate"] = { title = "El Sindicato", note = { { "El Sindicato ocupa los restos del poder de Alterac: poblados arruinados en las montañas, posiciones en Durnholde y un puesto en Stromgarde. Nobles desposeídos y criminales contratados componen un sustituto incómodo de un reino." }, { "Sus campamentos aún tienen oficiales y ambiciones, aunque su labor se reduzca al robo. Un señor caído puede conservar su título mucho después de perder los medios para vivir de él. En las laderas quizá se pida al viajero que cubra la diferencia." } } },
    ["tallstriders"] = { title = "Zancudos", note = { { "Los zancudos son aves de patas y cuello largos de las llanuras abiertas. Los de Mulgore y Los Baldíos son la visión más familiar de los pastizales después del kodo. Son bastante inofensivos hasta que se ven acorralados. Entonces dan coces capaces de romper un escudo." }, { "Los tauren los cazan por la carne y las plumas, con el agradecimiento que les pide la Madre Tierra. Los elfos de la noche de Costa Oscura y Frondavil conocen un pariente del bosque, el zancudo selvático." }, { "Sus huevos son apreciados. Sus madres lo saben." } } },
    ["thunder-lizards"] = { title = "Lagartos del trueno", note = { { "Un lagarto del trueno lleva la sorpresa de una tormenta en un cuerpo pesado de cuatro patas. Los Tronadores de Los Baldíos y las grandes bestias de Desolace pueden parecer herbívoros corrientes hasta que un rayo deja clara la diferencia." }, { "Su volumen ya impresionaría sin ese añadido. Los lagartos de los riscos de Sierra Espolón tienen la misma relación inquietante con el trueno. Un cielo despejado sobre el paso no garantiza una travesía tranquila." } } },
    ["troggs"] = { title = "Troggs", note = { { "Los troggs han salido de las profundidades a Dun Morogh, Loch Modan y Gnomeregan. Su fuerza es evidente. Su relación con la historia enana fue un descubrimiento bastante menos grato." }, { "Los registros de Uldaman describen un primer intento de dar vida a la piedra, seguido de los terráneos de los que descendemos los enanos. Esos registros convierten al trogg en un tema de estudio para la Liga además de un enemigo en la excavación." }, { "Así, la misma excavación puede ofrecer la historia de un antepasado y un habitante muy enfadado. La arqueología rara vez ordena sus temas de manera conveniente." } } },
    ["turtles"] = { title = "Tortugas", note = { { "El caparazón de una tortuga hace que el resto parezca un añadido hasta que asoma la cabeza. Las Quijafortes habitan lagos y ríos. Las grandes tortugas costeras de Tanaris y Azshara llevan el mismo diseño robusto al agua salada." }, { "Es fácil admirar su paciencia desde la orilla. De cerca, el pico merece el mismo estudio. Entre ambos hay un animal notablemente bien equipado para ocupar un tramo de agua sin que parezca esforzarse." } } },
    ["twilights-hammer"] = { title = "El Martillo Crepuscular", note = { { "El Martillo Crepuscular ha pasado de ser un clan orco a un culto con seguidores de muchos pueblos. Sus campamentos se reúnen en torno a poderes antiguos: en Cavernas de Brazanegra, cerca de ídolos oscuros y por las tierras elementales de Silithus." }, { "Los escritos del culto esperan el fin del mundo y sus invocadores trabajan para apresurarlo. Las túnicas y los atributos eruditos pueden dar a los campamentos apariencia de estudio. Los señores elementales invocados explican para qué sirven esos estudios." } } },
    ["venture-company"] = { title = "Ventura y Cía.", note = { { "Las obras de Ventura y Cía. suelen verse antes que sus obreros: una ladera talada en Sierra Espolón, petróleo en Los Baldíos, una mina abierta en los acantilados de Mulgore. Trituradoras, taladros y guardias contratados siguen a la concesión." }, { "Los goblins organizan buena parte de la labor, aunque el trabajo y la fuerza proceden de varios pueblos. Para los poblados cercanos, la compañía es menos una empresa lejana que un agujero que crece o una línea de árboles que retrocede. Sus cuentas pueden dar valor a la madera. Poner precio a la ladera vacía resulta más difícil." } } },
    ["water-elementals"] = { title = "Elementales de agua", note = { { "Un elemental de agua da a una fuente o estanque un habitante móvil hecho de su propia sustancia. El hielo es esa misma sustancia congelada, y sus elementales también tienen aquí su lugar. Los elementales contaminados de Vallefresno llevan la corrupción de su bosque a esa forma familiar." }, { "Frente a Azshara, los Señores del Agua de Hydraxis tienen un propósito muy distinto: enfrentarse a Ragnaros y sus servidores. Los magos también invocan elementales de agua. Una ola que se alza como un cuerpo es una visión llamativa, pero hace falta conocer algo del lugar y su historia para explicar por qué está allí." } } },
    ["wendigos"] = { title = "Wendigos", note = { { "Los wendigos de Dun Morogh viven en cuevas nevadas como El Cubil Pardo, donde el pelaje blanco desaparece contra la nieve. El tamaño de sus manos resulta menos fácil de pasar por alto." }, { "Sus pieles y crines son materia habitual de los encargos de caza locales. Para un enano joven, las colinas más allá del poblado pueden parecer una prolongación de su hogar. Un wendigo en la entrada de una cueva les da una escala muy distinta. No toda forma grande en la nieve es otro montañero." } } },
    ["wildkin"] = { title = "Lechúcicos", note = { { "Un lechúcico tiene el volumen de un oso bajo la cara y las plumas de un búho, combinación que merece un momento de atención tranquila. Los elfos de la noche consideran sagradas para Elune a estas criaturas." }, { "Los lechúcicos lunares viven en Costa Oscura, y las bestias búho ocupan Tierras del Interior y Cuna del Invierno. Sus nombres y temperamentos varían, pero los grandes ojos redondos siguen siendo distintivos. Un bosque que alberga uno puede hacer que uno se sienta observado de una forma que poco tiene que ver con una emboscada de cazadores." } } },
    ["wind-serpents"] = { title = "Serpientes aladas", note = { { "Las serpientes aladas trazan formas largas y brillantes en el cielo de Los Baldíos y Las Mil Agujas. Las alas emplumadas llevan un cuerpo que parece hecho para el suelo, y el relámpago da otro motivo para reconsiderar las apariencias." }, { "Algunos trols veneran a las serpientes aladas, y variedades más oscuras tienen un lugar entre los seguidores de Hakkar. Las criaturas salvajes siguen siendo llamativas por sí solas. Ante un acantilado desnudo, una serpiente alada puede aportar casi todo el color de la vista." } } },
    ["wolves"] = { title = "Lobos", note = { { "Un aullido puede hacer que todo un bosque parezca habitado. Los lobos viven desde los campos nevados de Dun Morogh hasta las arboledas de Elwynn. Sus distintos pelajes pertenecen a esos lugares tan naturalmente como los árboles. Los huargos, de mayor tamaño, dan a la silueta conocida una mandíbula más pesada." }, { "Los orcos han incorporado a los lobos a sus vidas como compañeros y monturas. Los cazadores jóvenes encuentran a las manadas salvajes en circunstancias muy distintas. El hambre resulta especialmente visible en los lobos famélicos junto a los caminos de los pueblos. A veces la distancia entre lo salvaje y una aldea es muy corta." } } },
    ["worgen"] = { title = "Ferocanis", note = { { "Arugal llamó a los ferocanis a Bosque de Argénteos para combatir a la Plaga y perdió el control de lo invocado. El Castillo de Colmillo Oscuro es ahora su bastión, mientras la cercana Piroleña sufre una maldición que transforma a sus habitantes al caer la noche." }, { "Los Nocturnos de Bosque del Ocaso pertenecen a otro relato atormentado, ligado a la Guadaña de Elune y a las invocaciones descritas por Velinde Cantoestelar. Su presencia no se explica simplemente señalando la torre de Arugal." }, { "Ambos lugares han adquirido la misma silueta terrible entre los árboles: una cabeza de lobo sobre un cuerpo erguido. Hay que seguir por separado las historias que hay detrás." } } },
    ["worms-and-grubs"] = { title = "Gusanos y larvas", note = { { "Buena parte del trabajo del mundo ocurre bajo la superficie. Las larvas se mueven por la podredumbre de las Tierras de la Peste, mientras excavadores mayores ocupan la arena y la piedra. Un suelo que parece vacío puede estar lleno de vida." }, { "Los gusanos de roca de las profundidades presentan el asunto al prospector con una fuerza poco habitual. Una criatura que vive cómodamente dentro de la tierra es un vecino incómodo para quien intenta abrir un túnel a través de ella. La roca, por lo visto, no estaba desocupada." } } },
    ["yetis"] = { title = "Yetis", note = { { "Los yetis ocupan cuevas de montaña desde Alterac hasta Cuna del Invierno, con una variedad lanuda también en las alturas de Feralas. Sus cuerpos anchos y pelajes espesos hacen que incluso una caverna grande parezca una vivienda estrecha." }, { "Sus cuernos han llamado la atención de Umi Risitas, en Vista Eterna. Necesita un par perfecto para el yeti mecánico con el que piensa asustar a sus amigos. Los yetis vivos están incómodamente unidos a las piezas." } } },
  },
  atlas = {
    [1411] = { { "Las barrancas rojas de Durotar encauzan los caminos entre sus poblados. Cerrotajo se alza en su cruce, con Orgrimmar al norte, el Poblado Sen'jin hacia la costa sur y el paso a Los Baldíos al oeste." }, { "El Valle de los Retos queda apartado del camino principal. El Fuerte de Tiragarde ocupa la costa oriental, mientras las Islas del Eco se ven frente a las tierras Lanza Negra sin estar a salvo en manos de los Lanza Negra." }, { "Fuera de Orgrimmar, las torres de zepelín dibujan un segundo horizonte sobre los muros del cañón. El viajero que busque aquí una travesía marítima debería mirar hacia arriba." } },
    [1412] = { { "Llanuras verdes y kodos que pastan bajo un gran cielo: el hogar de los tauren. Cima del Trueno se alza en las mesetas del norte. El Poblado Pezuña de Sangre está al sur, y el camino une ambos lugares antes de salir al este hacia Los Baldíos." }, { "Las llanuras son amables, en su mayoría. Los pozos de agua son de los tauren y merecen defensa. No así los gnolls de Roca Crines Pálidas, las arpías de Cresta Viento Furioso o la mina de Ventura y Cía. Los enanos de la excavación Bael'dun cavan donde los tauren preferirían que no lo hicieran." }, { "Roca Roja, al este, es lugar de reposo de los muertos honrados de los tauren. Camina allí en silencio." } },
    [1413] = { { "El Cruce da a Los Baldíos un centro desde el que los caminos se reparten con claridad: al norte hacia Vallefresno, al este a Trinquete, al oeste hacia Sierra Espolón y al sur por el Campamento Taurajo hacia el Gran Elevador." }, { "El terreno abierto facilita ver referencias lejanas y subestimar su distancia. Muros de espinas marcan territorio jabaespín. Los campamentos centauros y los oasis dispersos interrumpen las llanuras. Un lugar visible en el horizonte aún puede exigir una larga caminata." }, { "El puerto de Trinquete une la costa este con Bahía del Botín. Tierra adentro, el camino es la línea más fiable en un paisaje con espacio en todas las direcciones." } },
    [1416] = { { "El camino que sale de Trabalomas sube desde las laderas verdes hasta la nieve y los restos del reino de Alterac. Strahnbrad está ocupado por el Sindicato, mientras los ogros dominan buena parte de la capital arruinada. Una torre en una cresta es una referencia útil, pero promete poco refugio." }, { client = "classic", "Junto al Lago Lordamere, la cúpula violeta de Dalaran se ve desde las tierras bajas. Los magos reconstruyen detrás de ella. El camino lleva al viajero hasta el exterior de sus trabajos." }, { client = "forever", "Dalaran se alza junto al Lago Lordamere, donde la Archimaga Modera busca ayuda ante una crisis dentro de la ciudad. Las líneas ley alteradas han vuelto destructivas a sus construcciones. La ciudad tiene guardias suficientes para parecer ordenada desde el camino." }, { "Más arriba, cuevas de yetis y campos nevados interrumpen los senderos de montaña. El lago ofrece un punto fijo abajo. Entre las crestas, la siguiente curva suele quedar oculta." } },
    [1417] = { { "El Puente Thandol lleva el camino de Los Humedales a unas tierras de pendientes verdes y viejas fortificaciones. La Muralla de Thoradin marca el paso occidental hacia Trabalomas. Los grandes muros de Stromgarde se alzan sobre la costa suroeste." }, { "Refugio de la Zaga se encuentra entre las colinas centrales para la Alianza, mientras Sentencia guarda el nordeste para la Horda. La propia Stromgarde está dividida entre los defensores supervivientes, el Sindicato y los ogros. Un muro dibujado intacto en un mapa no tiene por qué encerrar un único poblado seguro." }, { "Los círculos de vínculo destacan en el terreno abierto. La Cala de Faldir se esconde bajo los acantilados del sur y resulta mucho menos visible desde el camino que desde el mar." } },
    [1418] = { { "El descenso desde Loch Modan deja atrás de golpe las tierras verdes. Crestas rojas dividen Tierras Inhóspitas en largos valles secos, con los muros de Kargath al oeste y las excavaciones de Uldaman junto al acceso norte." }, { "La Fortaleza de Angor es territorio Hierro Negro. Los campamentos ogros ocupan las colinas del sur y los dragonantes negros dominan el Barranco Lethlor al este. El tramo más despejado no tiene por qué ser el camino más tranquilo." }, { "Las excavaciones de la Liga ofrecen varias referencias útiles, aunque una tienda y un montón de escombros pueden parecerse mucho desde la siguiente cresta. Aquí el color de la piedra dice menos al topógrafo que su forma." } },
    [1419] = { { "El camino al sur desde el Pantano de las Penas llega al Castillo de Nethergarde, por encima de un yermo rojo. La fortaleza vigila el Portal Oscuro, cuyo marco aún se alza más al sur, en las tierras marcadas por la invasión." }, { "Los ogros Machacamiedo ocupan las colinas occidentales y los demonios dominan Escara Impía. Más allá de la fortaleza hay pocas referencias amistosas entre las que viajar. El Portal es bastante fácil de encontrar. Hallar un lugar cómodo a su lado es otra cosa." } },
    [1420] = { { "Los caminos de Claros de Tirisfal unen Camposanto, Rémol y las ruinas de la capital de Lordaeron, y luego siguen al este hacia el Baluarte. Las viejas granjas y molinos aún dividen el campo de forma reconocible, aunque muchos de sus habitantes estén muertos." }, { "El Monasterio Escarlata ocupa el nordeste, con puestos de vigilancia más allá. El Lago Aguasclaras tiene múrlocs en las orillas, y los bosques esconden sus propios peligros." }, { "Rémol es el principal poblado de los Renegados junto al camino. Cerca de las ruinas de la capital, las torres de zepelín unen estas tierras tranquilas con Orgrimmar y Grom'gol, un cruce de rutas inesperadamente concurrido sobre los árboles." } },
    [1421] = { { "Bosque de Argénteos se extiende entre Claros de Tirisfal y la frontera cerrada de Gilneas. El Sepulcro queda sobre el camino principal, que sigue al sur junto a Piroleña antes de girar hacia Trabalomas." }, { "El Castillo de Colmillo Oscuro se alza sobre Piroleña, cuyas calles conocidas se convierten en territorio ferocanis de noche. Más al sur, la Muralla de Cringrís cierra el camino a Gilneas. Es una frontera con un reino detrás, no un paso entre montañas." }, { "Los magos de Molino Ámbar ocupan los bosques del este. Entre sus dominios, la fortaleza y los poblados Renegados, una corta travesía en el mapa cruza varias reclamaciones muy distintas sobre el bosque." } },
    [1422] = { { "El camino entra por El Baluarte y cruza campos de cultivo arruinados hacia el Río Thondroril. Andorhal está cerca del centro. Sus caminos y edificios rotos aún marcan la antigua población cerealista." }, { "Vega del Amparo sigue siendo un bastión Escarlata en el norte. Al sur, Castel Darrow ocupa una isla en el Lago Darrowmere, con Scholomance debajo. El Campamento del Orvallo ofrece a la Alianza un puesto cercano." }, { "Las granjas son fáciles de identificar y difíciles de abordar. Sus calderas de peste han vuelto cada campo un terreno hostil separado, donde el mapa de caminos debe servir para algo muy distinto de recoger la cosecha." } },
    [1423] = { { "El Río Thondroril marca el acceso occidental a unas tierras de árboles muertos y granjas arruinadas. Los caminos llegan a Stratholme en el noroeste y a la Capilla de la Esperanza de la Luz en el este, donde el Alba Argenta mantiene un refugio." }, { "Mano de Tyr es un bastión Escarlata en el sudeste. Zul'Mashar ocupa las alturas del norte. Sobre Bosque de la Peste flota Naxxramas. Pocas referencias son tan fáciles de reconocer o tan poco gratas de ver." }, { "Los edificios de Villa Darrow aún marcan un pueblo en la llanura, aunque sus habitantes pertenecen a un relato más atormentado. Aquí un mapa puede seguir siendo perfectamente exacto después de perderse casi todo lo que describe." } },
    [1424] = { { "Trabalomas queda entre las laderas de Alterac y el mar. Costasur ofrece a la Alianza un puerto y una población costera. Molino Tarren es el puesto de los Renegados en el interior. Entre ambos quedan granjas y caminos disputados." }, { "La ruta oriental llega a Arathi por la Muralla de Thoradin. Otras llevan al oeste a Bosque de Argénteos, al norte a Alterac y hacia las alturas de Tierras del Interior. Los muros arruinados de Durnholde destacan junto a los caminos del este, aunque ahora el Sindicato ocupa la antigua fortaleza de internamiento." }, { "Deberían ser tierras fáciles de cruzar: colinas bajas, campos trabajados y abundantes caminos. La dificultad rara vez está en el suelo." } },
    [1425] = { { "El acceso occidental sube desde Trabalomas hasta Pico Nidal, donde los grifos de los Martillo Salvaje comparten las alturas sobre el valle. El camino serpentea después al este entre colinas boscosas y antiguos dominios trols." }, { "Jintha'Alor sube en terrazas al sudeste, mientras el gran árbol de Seradane marca tierras de dragones al norte. El Poblado Sañadiente ocupa la costa este y ofrece a la Horda su propio puesto bajo las colinas." }, { "La altura de Pico Nidal ofrece una buena primera vista, pero buena parte de la ruta desaparece entre árboles antes de llegar al mar. Los Martillo Salvaje han elegido unas tierras excelentes para viajar en grifo." } },
    [1426] = { { "Nieve, piedra y enanos, en ese orden. Los valles corren de este a oeste bajo los picos que esconden Forjaz, y el único camino los sigue: desde el Valle de Crestanevada, por el túnel hasta Kharanos, subiendo a la gran puerta de la ciudad y siguiendo al este por el paso hacia Loch Modan." }, { "Kharanos tiene la destilería Cebatruenos y el mejor fuego de estas tierras. Al oeste el terreno pertenece a los trols Peloescarcha, y más allá Gnomeregan se alza envenenada tras sus muros. Los gnomos no regresan a casa. Tú tampoco deberías entrar sin una buena razón y mejores amigos." }, { "Lleva una capa de repuesto y no abandones el camino durante una ventisca. La nieve es profunda y a los troggs de Crestanevada les da igual que hayas perdido el rumbo." } },
    [1427] = { { "La Caldera abre un gran pozo en el centro de La Garganta de Fuego, con explotaciones Hierro Negro bajo la superficie. Desde arriba, los andamios y las entradas de las minas solo muestran parte de las tierras que quizá deba cruzar el viajero." }, { "Puesto del Torio es el puesto de la Hermandad del torio en el norte. La Montaña Roca Negra ofrece el paso al sur hacia Las Estepas Ardientes. Los accesos desde las tierras vecinas llegan a la garganta por aberturas más estrechas entre las montañas." }, { "Los montones de escoria y las máquinas rotas son referencias útiles aquí. Es un paisaje en actividad, por arruinado que parezca desde la siguiente cresta." } },
    [1428] = { { "La Montaña Roca Negra domina el horizonte del norte y da a casi todos los caminos de las Estepas Ardientes la misma gran referencia. El acceso desde Montañas Crestagrana sube hasta tierras oscuras de ceniza, donde crestas rotas y viejas fortificaciones interrumpen la llanura." }, { "La Vigilia de Morgan ocupa las alturas del este para la Alianza. Peñasco Llamarada ofrece a la Horda un puesto más al norte. Entre ambas quedan campamentos Roca Negra, dragonantes y restos de batallas antiguas." }, { "La montaña es también el paso hacia La Garganta de Fuego. Desde fuera parece un muro macizo al final del país. Dentro, el tamaño de sus puentes y cámaras se convierte en el siguiente problema del viajero." } },
    [1429] = { { "El camino principal de Elwynn va de Ventormenta a Villadorada y sigue al este hacia Montañas Crestagrana. Villanorte ocupa un valle resguardado al norte, mientras el cruce occidental lleva a Páramos de Poniente. Granjas, puentes y lagos dan a estas tierras referencias excepcionalmente claras." }, { "Las minas son menos ordenadas que los campos de encima: los kóbolds ocupan Mina Abisal y Cantera de Jaspe, y la actividad Defias llega bien adentro del bosque. Al suroeste, los campamentos Zarparrío vuelven peligroso el bosque abierto junto al río." }, { "Ventormenta nunca está lejos en millas. Un granjero que espera ayuda con una mina o un campamento quizá mida la distancia de otra manera." } },
    [1430] = { { "El camino entre Bosque del Ocaso y el Pantano de las Penas cruza el Paso de la Muerte entre roca desnuda y precipicios. En el mapa el trayecto principal parece corto, pero los árboles muertos y los edificios vacíos dan pocos motivos para entretenerse." }, { "Un ramal del sur baja hacia Karazhan y el pueblo abandonado a sus pies. La torre permanece sellada en estos días. Su altura es una referencia excelente sobre un país donde casi todo lo demás parece haber dejado de crecer." } },
    [1431] = { { "Los caminos de Bosque del Ocaso atraviesan un bosque que deja llegar poca luz al suelo. Villa Oscura es el principal refugio del este, con la Guardia Nocturna guardando sus accesos. Más allá está el Paso de la Muerte. El camino del sur baja hacia Vega de Tuercespina." }, { "Al oeste, Cerro del Cuervo y su cementerio ocupan tierras mucho menos seguras de lo que sugieren los nombres familiares de granjas del mapa. El Vergel Pútrido y las casas abandonadas conservan la forma de un valle habitado, pero poca de su antigua vida." }, { "Los caminos aún unen los lugares para los que se construyeron. Eso los convierte en referencias útiles, incluso cuando el destino se ha vuelto un sitio por el que uno preferiría pasar de largo." } },
    [1432] = { { "Un lago largo contenido por la Presa de las Tres Cabezas, la mejor obra de ingeniería enana fuera de Forjaz, y no admitiré discusiones. Thelsamar está en la orilla occidental, junto al camino de Dun Morogh, que sigue al norte hacia Los Humedales y al sur hacia Tierras Inhóspitas." }, { "El Valle de los Reyes tiene reyes de piedra que vigilan el paso. El resto del país necesita vigilancia: troggs en el Valle Rompecantos, kóbolds en las minas y ogros en la Fortaleza de Mo'grosh, en las colinas del nordeste." }, { "Los altos elfos de Cabaña del Errante van a lo suyo y conocen estas tierras mejor que cualquier enano. Pregúntales antes de ir de caza." } },
    [1433] = { { "Villa del Lago se encuentra en la orilla occidental del Lago Sempiterno, donde puentes y caminos unen los accesos desde Elwynn y Bosque del Ocaso. El agua da al valle un centro amplio y hermoso y un conjunto de referencias excepcionalmente claro." }, { "Las alturas del este son otra cosa. Fuerte de Petravista está en manos de los Roca Negra y los campamentos gnoll ocupan las crestas entre los poblados y las montañas." }, { "Desde Villa del Lago, la otra orilla parece lo bastante cercana para formar parte de las propias tierras del pueblo. Los guardias la ven con mucha menos tranquilidad." } },
    [1434] = { { "Vega de Tuercespina va del extremo sur de Bosque del Ocaso a Bahía del Botín a través de una larga extensión de selva. El camino pasa por las expediciones del norte y el Grom'gol de la Horda antes de llegar al puerto goblin del otro extremo." }, { "Las ruinas y los campamentos habitados quedan cerca, tras los árboles: el recinto de Kurzen, los poblados trols, el territorio Mosh'Ogg y los accesos a Zul'Gurub. Un claro ofrece vistas sin garantizar una parada segura." }, { "Bahía del Botín está construida sobre roca escarpada alrededor de su puerto, con el barco a Trinquete bajo los niveles del pueblo. Tras tanta selva, una ruta medida sobre aguas abiertas es un cambio bienvenido." } },
    [1435] = { { "El camino occidental llega del Paso de la Muerte y cruza el pantano hacia Rocal, el principal poblado de la Horda. Un ramal del sur lleva a Las Tierras Devastadas. Fuera del camino, el agua poco profunda interrumpe una y otra vez lo que parece suelo firme." }, { "La Charca de Lágrimas cubre el Templo de Atal'Hakkar. El Retiro Fangoso queda más al este, mientras el Puerto alberga refugiados draenei en el norte. Llegar a la costa supone ir mucho más allá del último tramo de camino fiable." }, { "El pantano ofrece poca altura desde la que orientarse. Un templo sumergido bajo un lago es una referencia particularmente inútil para quien intenta encontrar el lago." } },
    [1436] = { { "El camino de Páramos de Poniente cruza desde Elwynn los campos abiertos y sigue hasta Colina del Centinela. La Milicia Popular guarda la torre, que sigue orientando sobre campos de los que a menudo han huido sus dueños." }, { "Arroyo de la Luna queda más al sur, con Minas de la Muerte debajo. En otros lugares, los campamentos Defias y los gólems de cosecha hostiles ocupan tierras aún divididas por setos y caminos de granja." }, { "El faro es una referencia clara desde la costa occidental, aunque los campamentos múrloc interrumpen el acceso. En Páramos de Poniente hay espacio de sobra para ver a lo lejos. Lo difícil es saber qué espera en el siguiente campo." } },
    [1437] = { { "Dun Algaz lleva el camino de Loch Modan a amplios humedales, donde las rutas principales se separan hacia el Puerto de Menethil al oeste y el Puente Thandol al norte. El camino elevado da una línea más firme por tierras divididas por aguas poco profundas." }, { "Los barcos de Menethil unen Los Humedales con Auberdine y Theramore. Tierra adentro, los campamentos Faucedraco ocupan las colinas, los Hierro Negro dominan Dun Modr y los dragonantes rojos guardan los accesos a Grim Batol, al este." }, { client = "forever", "Más allá de la antigua excavación de Whelgar, la nueva llega a construcciones antiguas. Las reliquias llevadas a Whelgar dan a la Liga buenos motivos para conservar el acceso en sus mapas." }, { "Fuera del camino, los juncos pueden ocultar el borde de un canal con tanta facilidad como un crocolisco. La ruta más corta al siguiente alto puede contener mucha más agua de la que sugiere el mapa." } },
    [1438] = { { "Teldrassil sostiene un bosque entero y habitado por encima del mar. El camino va de Cañada Umbría por Dolanaar a Darnassus, con ramales hacia claros y túmulos que pueden parecer muy alejados del borde de una isla." }, { "Tejemadera y los dominios Tuercepinos interrumpen el bosque habitado. Las pozas dan referencias frecuentes, aunque sus orillas cerradas revelan poco de la altura que hay debajo." }, { "La bajada pasa por el portal de Darnassus a Aldea Rut'theran, de donde los barcos parten entre las raíces. Conviene recordar esa ruta: una costa sirve de poco al viajero cuando queda tan por debajo del camino." } },
    [1439] = { { "Costa Oscura es un largo viaje por una costa estrecha. Auberdine reúne los caminos y el tráfico marítimo en el centro, con barcos a Aldea Rut'theran y, al otro lado del mar, al Puerto de Menethil. El camino del sur lleva a Vallefresno." }, { "La orilla y los bosques del interior ofrecen recorridos muy distintos. Los naufragios y los campamentos múrloc interrumpen las playas. Tierra adentro están las ruinas encantadas de Ameth'Aran y Bashal'Aran, los campamentos Bosque Negro y la torre de Althalaxx." }, { "El mar es una guía constante cuando los árboles ocultan el camino. También es la razón de que tantos barcos rotos se hayan convertido en referencias." } },
    [1440] = { { "El camino principal de Vallefresno atraviesa un bosque profundo hasta Astranaar y luego sigue al este, hacia los campamentos Grito de Guerra y Azshara. Otros ramales llevan al norte a Costa Oscura, al oeste por el paso de montaña hacia Sierra Espolón y al sur hasta La Empalizada de Mor'shan." }, { "Los poblados quedan lo bastante separados como para que el bosque se cierre alrededor del viajero entre ellos. En la costa, La Ensenada de Zoram se abre hacia ruinas ocupadas por naga. En el interior, los campamentos fúrbolg y las tierras demoníacas junto a Cerro Lumbrevil convierten varios claros tentadores en malos lugares para detenerse." }, { "Los puentes y el lago de Astranaar ofrecen una referencia fija y bienvenida entre tantos árboles. Más allá, rara vez se ve lo bastante lejos como para abarcar el camino que queda por delante." } },
    [1441] = { { "El Gran Elevador baja desde Los Baldíos a un cañón lleno de pilares de piedra. El Poblado Viento Libre se alza sobre uno de ellos, al que se llega con sus propios elevadores. Abajo, el camino se abre paso entre acantilados hacia el Desierto de Sal." }, { "La Cumbre de la Nube Negra es terreno Tótem Siniestro, mientras centauros y arpías ocupan otros cañones laterales. Los pilares son buenas referencias hasta que el siguiente los oculta." }, { "Al este, la tierra se abre de pronto en salinas y el Circuito del Espejismo. Las máquinas gnómicas y goblin llenan un país lo bastante amplio, por fin, para ver lejos sin levantar la cabeza." } },
    [1442] = { { "Los caminos de Sierra Espolón suben por valles estrechos, con el Refugio Roca del Sol en el centro de la sierra y Malaka'jin cerca de los accesos del sur. Los elfos de la noche dominan la Cima del Espolón en el lejano norte." }, { "Las talas de Ventura y Cía. han abierto grandes heridas en el bosque. Más al oeste, la Vega Carbonizada es terreno quemado ocupado por arpías y otros peligros. La Senda de las Tejedoras da una advertencia más literal con su nombre." }, { "El paso de montaña a Vallefresno y los caminos que bajan hacia Los Baldíos y Desolace convierten este lugar en un cruce. La distancia por sí sola mide mal un viaje con tantas curvas y subidas." } },
    [1443] = { { "Desolace se abre bajo Sierra Espolón en crestas grises y amplias extensiones expuestas. Punta de Nijel ocupa las alturas del norte para la Alianza. La Aldea Cazasombras está abajo, en la costa occidental, para la Horda. El camino del sur llega a Feralas." }, { "Los territorios centauros llenan buena parte del interior, con el Cementerio de Kodos entre ellos. La Fortaleza del Hacha de Trueno y el Aquelarre Mannoroc marcan tierras hostiles de otra clase. En la costa, el terreno cae hacia aguas ocupadas por naga." }, { "Los huesos hacen que el cementerio destaque desde lejos. La orilla de Cazasombras ofrece algo más amable a la vista: un poblado construido hacia el mar en vez de otro campamento en el polvo." } },
    [1444] = { { "Feralas se cierra sobre el camino con grandes troncos y maleza densa. El paso del norte baja de Desolace. Hacia el este, la ruta llega al Campamento Mojache y continúa hacia Las Mil Agujas." }, { "El Bastión Plumaluna está frente a la costa, en la Isla de Sardor, y se llega en barco desde la orilla occidental. En el interior, La Masacre se alza sobre el bosque, con ogros en buena parte de la ciudad arruinada. El gran árbol de Rama Oniria marca territorio de dragones más al norte." }, { "La copa puede ocultar una pendiente considerable hasta que el camino empieza a subirla. Un mapa de Feralas necesita espacio para la altura además de la distancia." } },
    [1445] = { { "El camino de Los Baldíos entra en Marjal Revolcafango entre juncos y aguas someras, hasta llegar a la calzada y al puerto de Theramore. De la ciudad insular salen barcos hacia Menethil. El Poblado Murohelecho, un poblado de la Horda con ogros Quebrantarrocas entre sus habitantes, se alza en el pantano del noroeste." }, { "Los dominios de Onyxia quedan al sur, en Ciénaga de Fuego. En otros lugares, canales y riberas bajas dividen un suelo que de lejos parece continuo. Una curva del camino suele orientar mejor que los árboles, que por desgracia se parecen mucho entre sí." }, { "Desde las construcciones de piedra de Theramore, tierra firme parece muy cercana. Tras unas curvas por el pantano, puede parecer que la ciudad ha desaparecido detrás de él." } },
    [1446] = { { "El descenso desde Las Mil Agujas llega a Gadgetzan, cerca del extremo norte de Tanaris. Sus muros y el Puerto Bonvapor de la costa oriental son puntos fijos útiles en un desierto cuyo sur está mucho menos habitado." }, { "Zul'Farrak está en el noroeste, los ogros Machacaduna ocupan el interior y la Cala del Aparejo Perdido resguarda piratas tras las colinas del este. Las Cavernas del Tiempo se abren entre las montañas más al sudeste." }, { "La ruta occidental acaba bajando a Un'Goro. Desde el borde, el cráter verde parece otro país por completo, un descubrimiento especialmente agradable después de tanta arena." } },
    [1447] = { { "El camino llega desde Vallefresno por encima de una costa de templos rotos y árboles rojos y dorados. Punta Talrendis y Valormok ofrecen pequeños puestos cerca del acceso occidental. Más al este, las colinas caen abruptamente hacia la Bahía de la Tempestad." }, { "Los naga ocupan buena parte de la orilla, mientras los campamentos de sátiros y las expediciones élficas dominan terreno entre las ruinas. Azuregos recorre el sur. Una línea recta en el mapa puede ocultar tanto un acantilado como el largo rodeo para evitarlo." }, { client = "classic", "La gran puerta de las colinas del norte está señalada como Bastión de los Fauces de Madera, pero permanece cerrada. Los túneles fúrbolg que llevan a Claro de la Luna y Cuna del Invierno están en Frondavil, bastante al oeste de aquí." }, { client = "forever", "La gran puerta de piedra de las colinas del norte conduce al Bastión Faucenegra, hogar de una tribu fúrbolg corrompida. Los túneles de los Fauces de Madera a Claro de la Luna y Cuna del Invierno siguen bastante al oeste, en Frondavil." } },
    [1448] = { { "El camino de Frondavil sube desde Vallefresno por un bosque cuyos árboles muertos y enfermos dejan grandes huecos en la copa. El Santuario Esmeralda está cerca del acceso sur. El Puesto del Veneno y el Claro Ramaespolón ofrecen puestos separados más adelante en el valle." }, { "Jaedenar y los campamentos Fuego de Jade ocupan algunas de las tierras más corrompidas. En el extremo norte, los túneles de los Fauces de Madera llevan a Claro de la Luna y Cuna del Invierno, siempre que sus guardias permitan pasar." }, { "Aquí una poza verde no consuela a un paisaje sediento. El color pertenece al daño y a menudo se distingue entre los árboles antes de ver la propia poza." } },
    [1449] = { { "El sendero que baja de Tanaris revela Un'Goro de golpe: selva espesa en torno a la Cresta del Penacho en Llamas, con pozos de alquitrán y aguas termales entre el verde. El Refugio de Marshal se apoya en el borde norte. La salida hacia Silithus sube por el noroeste." }, { "El volcán central es una referencia excelente y un terreno difícil. Lejos de él, la copa esconde raptores, demosaurios y el territorio silítido de La Cicatriz Serpenteante. Es más fácil abarcar el cráter desde arriba que cruzarlo por abajo." }, { client = "classic", "Hay cristales brillantes por toda la cuenca, y los pilones ofrecen otro tema para las investigaciones de la expedición. El mapa señala sus posiciones. Explicarlos es un trabajo distinto." }, { client = "forever", "El Bancal del Creador sitúa los rastros titánicos del cráter en el mapa junto a los pilones y cristales dispersos. Un nombre para un lugar antiguo deja mucha selva sin explicar." } },
    [1450] = { { "El Lago Elune'ara ocupa el centro de Claro de la Luna, con Amparo de la Noche en su orilla y el santuario del Guardián Rémulos cerca. Los druidas llegan por su propia magia. Los demás viajeros suelen alcanzar el valle por los túneles de los Fauces de Madera desde Frondavil." }, { "El Círculo Cenarion recibe aquí a ambas facciones, y el Festival Lunar trae visitantes de mucho más lejos. La calma es real, aunque la lucha en torno al Sueño Esmeralda haya llegado incluso a este valle." }, { "Para el topógrafo, el lago es una constante bienvenida: una referencia amplia y abierta tras el paso estrecho por la montaña." } },
    [1451] = { { "El sendero de Un'Goro llega a Silithus por el extremo nordeste de un gran desierto. El Fuerte Cenarion se alza sobre el interior y ofrece un punto fortificado desde el que calcular las distancias entre colmenas." }, { "El Martillo Crepuscular ocupa campamentos por todo el yermo, mientras el gran Muro del Escarabajo marca Ahn'Qiraj al sur. Los montículos silítidos interrumpen lo que de otro modo podría parecer arena despejada." }, { "La Aldea del Viento del Sur sigue siendo un poblado reconocible en el mapa y una ruina sobre el terreno. Los caminos y las torres son tan escasos que un único edificio en pie puede resultar decisivo para orientarse." } },
    [1452] = { { "El paso de los Fauces de Madera se abre a los grandes campos nevados de Cuna del Invierno, con Vista Eterna reuniendo el comercio cerca del centro. El pueblo goblin ofrece techo a ambas facciones y un cruce de rutas entre las montañas." }, { "La Aldea Estrella Fugaz queda al oeste, los dragonantes azules de Mazthoril dominan las cuevas del sur y el territorio yeti sube más allá de las Colinas Cardo Nevado. Los campamentos Nevada interrumpen otros accesos entre la nieve." }, { "La Garganta Negro Rumor corta el extremo sur, donde los demonios ponen un límite sombrío al valle. Las aguas termales ofrecen referencias más amables: agua abierta y oscura y vapor que se alza contra mucho blanco." } },
    [1453] = { { "La puerta de Ventormenta lleva el camino de Elwynn junto a las estatuas del Valle de los Héroes y hasta el Distrito de Mercaderes. Los canales separan los barrios, y los puentes hacen buena parte del trabajo que una gran avenida haría en otra ciudad." }, { "Los grifos parten del Distrito de Mercaderes, y el Tranvía Subterráneo une el Distrito de los Enanos con Forjaz. La Catedral destaca con facilidad por encima de los tejados. Las Mazmorras ofrecen una referencia menos tranquilizadora junto al agua." }, { "La piedra blanca de la ciudad sigue siendo una respuesta impresionante a su antigua ruina. Cruzarla con eficacia exige prestar algo más de atención a los puentes que al horizonte." } },
    [1454] = { { "Orgrimmar sigue los pliegues de un cañón de roca roja, con la puerta principal abierta al sur, hacia Durotar. Rampas y pasadizos unen los valles del interior. Dos destinos cercanos en un mapa plano pueden exigir una larga subida para pasar de uno al otro." }, { "El Fuerte Grommash está en el Valle de la Sabiduría, y los jinetes del viento parten de una torre alta. Fuera de los muros, los zepelines unen la capital con Entrañas y Grom'gol." }, { "El cañón forma parte de la fortaleza tanto como los muros construidos. Su forma se comprende mejor desde arriba, lo que resulta conveniente una vez encontrados los jinetes del viento." } },
    [1455] = { { "La puerta de Forjaz da paso desde la nieve a una ciudad ordenada en torno a la Gran Fundición. El anillo principal une la zona común, el Trono, Ciudad Manitas y la Sala de los Exploradores. Saber en qué dirección recorrerlo ahorra bastantes pasos." }, { "El Tranvía Subterráneo sale de Ciudad Manitas hacia Ventormenta, y los grifos parten junto a la Gran Fundición. La sala de la Liga ofrece un destino más tranquilo, aunque a veces las piezas expuestas atraen tanta discusión como la casa de subastas." }, { client = "forever", "Bajo la ciudad, las cavernas de Antigua Forjaz llevan al Salón de los Feudales. Los intrusos Hierro Negro han encontrado entrada a sus cámaras inferiores. La ciudad ha adquirido otra frontera justo bajo los pies del rey." } },
    [1456] = { { "La ciudad de los tauren sobre las mesetas del norte de Mulgore, unidas por puentes de cuerda y accesibles mediante grandes elevadores desde la llanura." }, { "Cada alto tiene su propósito: el Alto de los Ancestros para los ancianos y druidas, el Alto de los Espíritus para los chamanes y sacerdotes, el Alto de los Cazadores para los cazadores y guerreros. El banco y la casa de subastas están en el alto central, y los jinetes del viento parten de la torre." }, { "Los puentes se balancean. No mires abajo y no corras." } },
    [1457] = { { "Darnassus se abre en torno al agua y a amplios puentes en lo alto de Teldrassil. El Templo de la Luna domina el sur de la ciudad, mientras mercaderes y artesanos ocupan los bancales del norte." }, { "El camino del este lleva a Dolanaar. En el lado occidental de la ciudad, el portal permite bajar a Aldea Rut'theran y sus barcos. Un topógrafo acostumbrado a medir la altura de una ciudad desde el suelo necesita hacer algunos ajustes aquí." } },
    [1458] = { { "Entrañas yace bajo la capital arruinada de Lordaeron. Se llega por los elevadores bajo la antigua sala del trono o por el acceso exterior de las cloacas. Dentro, pasadizos circulares y canales verdes unen los barrios." }, { "El banco central es una referencia útil. El Barrio Real y los trabajos de los boticarios quedan más adentro. Para llegar hace falta atender a los niveles además de a los giros." }, { "En la superficie, las torres de zepelín se alzan fuera de las ruinas. El viajero que llega por aire puede tener la ciudad a pocos pasos y aun así tardar un rato en encontrar la bajada correcta." } },
    [2521] = { { "Zephras es una isla habitada suspendida en Muro Celeste. Valanaar ocupa el extremo sudeste, con la sede del sumo anciano y los muelles del cielo. Ban'aethal, en el norte, se ha evacuado al fallar los pilones que sostienen la isla." }, { "Las granjas del sur dan paso a las Tierras Altas de Shen'dar, luego a pueblos, santuarios y el Bosque Ventosombra. En tierra corriente, un camino roto es una molestia. Aquí el propio suelo se ha convertido en parte de la incertidumbre del mapa." }, { "Los surcacielos parten de Valanaar hacia Dalaran y Mulgore. Las rutas a Anvilas y Siroccas han quedado en silencio, dejando esas otras islas fuera de las referencias actuales del viajero." } },
  },
  herbs = {
    [13463] = { { "La hojasueño se recoge entre las ruinas de Azshara y dentro de La Masacre, además de en las tierras marcadas por las cicatrices que rodean la Montaña Roca Negra." }, { "Las pociones de protección superior la emplean contra el fuego, la escarcha, la Naturaleza, las Sombras y el daño Arcano. El Frasco de sabiduría destilada también la necesita." } },
    [13464] = { { "El sansam dorado se recoge en Cráter de Un'Goro y Azshara, y por tierras tan dañadas como Frondavil y las Tierras de la Peste del Este." }, { "Lo emplean brebajes sublimes de sanación y de rejuvenecimiento. Los suministros curativos traídos de esos lugares no se quedan sin trabajo al llegar." } },
    [13465] = { { "La salviargenta de montaña se recoge en Cuna del Invierno y Cráter de Un'Goro, pese a las vistas tan distintas que ofrece el fondo del cráter." }, { "Se emplea en Poción de curación sublime y, con flor de peste, sirve para hacer el Elixir de la mangosta." } },
    [13466] = { { "La flor de peste se recoge en las dos Tierras de la Peste, donde encontrar vegetación útil entre los campos arruinados supone un pequeño alivio." }, { "La emplean las Poción de purificación y las Poción de sangre de mago. La salviargenta de montaña la acompaña en el Elixir de la mangosta. Algo recogido en esas tierras asoladas aún puede servir a los vivos." } },
    [13467] = { { "El setelo forma parte de las rutas de recolección de Cuna del Invierno. La nieve ofrece al herborista un paisaje inusualmente uniforme donde aprender a encontrarlo." }, { "Lo emplean las Poción de maná sublime y las Poción de purificación, junto con el Frasco de sabiduría destilada." } },
    [13468] = { { "El loto negro es un hallazgo raro en un pequeño número de regiones peligrosas. Un recolector que lo descubre tiene buenos motivos para recordar el lugar." }, { "Lo necesitan los grandes frascos, incluidos los de titanes y poder supremo. Muchos manojos se reponen en una ronda corriente. Este suele decidir cuándo puede empezar el trabajo más ambicioso." } },
    [19726] = { { "La vid de sangre no crece en ningún lugar que un mapa pueda mostrar. Los herboristas solo la encuentran en Zul'Gurub, escondida entre la hojasueño, la solea, el loto morado, el sansam dorado y la salviargenta de montaña de la ciudad trol, como si el lugar hubiera entretejido sus plantas con algo más rojo." }, { "La artesanía Zandalar se apoya en ella: placas de alma de sangre, el jubón, los leotardos y las botas de vid de sangre, cuero de tigre de sangre y las Gafas Vid de sangre y Lentes Vid de sangre de los ingenieros. También la piden los patrones del Círculo Cenarion, desde Abrazo de Gaea hasta las piezas de parra férrea, y una Bolsa de tela de inferi del Núcleo se lleva su parte. Quien la recoge en Zul'Gurub rara vez la conserva mucho tiempo." } },
    [2447] = { { "La flor de paz resulta familiar en los primeros caminos que salen de casa y sigue siendo útil mucho después de que un herborista haya aprendido nombres más raros." }, { "Con hojaplata se convierte en una Poción de curación menor. Tiene algo agradable encontrar el comienzo de un remedio en tierras donde un aprendiz aún reconoce el camino de vuelta." } },
    [2449] = { { "La raíz de tierra aparece por las regiones habitadas e incluso dentro de las Cuevas de los Lamentos. Es una de las primeras raíces que un herborista aprende a reconocer." }, { "El Elixir de fuerza de león y el Elixir de entereza menor empiezan con ella. Nombres tan imponentes tienen ingredientes modestos, lo cual reconforta a un aprendiz." } },
    [2450] = { { "La brezospina resulta familiar en Los Baldíos y en las regiones boscosas al otro lado del mar. El cardoveloz puede acompañar a los tallos recogidos." }, { "La necesitan los brebajes de sanación y las Poción de ira. El mismo manojo puede ayudar a alguien a recuperarse de una pelea o a prepararse para empezar otra." } },
    [2452] = { { "El cardoveloz acompaña a la marregal y la brezospina, en lugar de crecer en un matorral propio. Un herborista que lo busque debe fijarse en lo que da la otra recolección." }, { "Los pícaros preparan Té de cardo con él y los alquimistas lo emplean en brebajes de presteza y de natación." } },
    [2453] = { { "La hierba cardenal está lo bastante extendida como para hacerse habitual en la ronda de recolección. Las Cuevas de los Lamentos y las Cavernas de Brazanegra también la tienen, para aquellos cuyos encargos los llevan bajo tierra." }, { "Las Poción de curación y el Elixir de resistencia al envenenamiento le dan trabajo seguro." } },
    [3355] = { { "La acérita salvaje resulta familiar a los herboristas que recorren las colinas de Tierras Altas de Arathi y los terrenos rocosos de Sierra Espolón." }, { "El Elixir de defensa y el Elixir de entereza la emplean. La armadura corresponde al herrero, pero el alquimista tiene algunas aportaciones antes de que el viajero se la abroche." } },
    [3356] = { { "La sangrerregia aparece en una amplia extensión de terreno, desde colinas boscosas hasta el árido interior de Kalimdor. Su valor no depende de una búsqueda difícil." }, { "La emplean los brebajes de sanación superior y las pociones de maná, y los peleteros la necesitan para los Guantes de herborista. Una hierba que ayuda a fabricar guantes de recolección ocupa un lugar agradable en el oficio." } },
    [3357] = { { "La vidarraíz se encuentra en zonas húmedas de ambos continentes, con buena parte de la recolección en pantanos y riberas." }, { "La necesitan las Poción de curación superior y el Elixir del caminante acuático." } },
    [3358] = { { "El mostacho de Khadgar tiene un nombre que el viajero recordará fácilmente, incluso antes de saber dónde buscarlo. La hierba aparece en varias regiones boscosas y pantanosas." }, { "La emplean las Poción de maná superior, el Elixir de intelecto superior y el Aceite escarchado. El nombre del archimago ha acabado en un estante muy concurrido." } },
    [3369] = { { "El musgo de tumba se recoge en lugares donde un herborista difícilmente se sentirá del todo a solas, entre ellos Bosque del Ocaso, Desolace y el cementerio de Zahúrda Rajacieno." }, { "Lo necesitan el Aceite de las Sombras y las Poción de protección de las Sombras. Sus usos encajan bien con los encargos que llevan a un recolector entre las tumbas." } },
    [3818] = { { "La pálida se recoge por las tierras intermedias, y también hay matas dentro del Monasterio Escarlata y Horado Rajacieno." }, { "Los pícaros preparan Polvo cegador con ella. Los alquimistas la emplean en pociones para hacerse invisible y para detectar lo invisible. La misma hierba contribuye a los dos bandos de un encuentro difícil." } },
    [3819] = { { "La invernalia reserva al herborista un viaje concreto, hacia la nieve de las Montañas de Alterac. Una planta conocida es buena compañía en tierras donde resulta fácil perder el camino." }, { "La necesitan el Aceite escarchado, las Poción de protección de Escarcha y el Elixir de poder de Escarcha. La hierba de montaña tiene trabajo a ambos lados de la lucha contra el frío." } },
    [3820] = { { "El alga estranguladora aparta al herborista del sendero y lo lleva al agua costera. La propia recolección ofrece un buen motivo para conocer lo que crece bajo la superficie." }, { "El Elixir de respiración acuática es uno de sus usos, junto con brebajes de maná y Poción de acción libre. La planta aporta un remedio para una molestia que aparece al recogerla." } },
    [3821] = { { "La espina de oro se gana un lugar en la bolsa de trabajo por la variedad de sus usos. Sus tierras de recolección incluyen las colinas de Tierras Altas de Arathi y los bosques de Feralas." }, { "La necesitan brebajes de maná superiores, elixires de agilidad y Poción de protección de Escarcha." } },
    [4625] = { { "La flor de fuego forma parte de las rutas de recolección por Tanaris, Tierras Inhóspitas y La Garganta de Fuego. Ninguna es una tierra amable donde detenerse a llenar una bolsa." }, { "El Combustible de cohete goblin y el Aceite de inmolación dan una idea bastante clara de sus usos. La Piedra del filósofo también la necesita, para alquimistas con otras ambiciones para el mismo manojo." } },
    [765] = { { "La hojaplata comparte las primeras bolsas de recolección con la flor de paz. Una planta no necesita ser rara para hacerse indispensable en el banco de trabajo." }, { "Los brebajes menores de sanación y de maná la requieren. Esos dos usos explican por qué un alquimista que ha recogido de sobra puede descubrir, en muy poco tiempo, que no era suficiente." } },
    [785] = { { "La marregal es un hallazgo útil en los caminos más allá de los primeros asentamientos. A veces la acompaña el cardoveloz y una sola parada da una segunda recompensa." }, { "Los alquimistas emplean marregal en brebajes de maná y en el Elixir de sabiduría. El nombre crea grandes expectativas. Lo que hace por un joven hechicero resulta más que suficiente." } },
    [8153] = { { "El atriplex salvaje se recoge con el loto morado, un hallazgo adicional en tierras que ya merecía la pena recorrer en busca de la flor." }, { "Los peleteros la necesitan para el cuero salvaje y los sastres para el tejido onírico. La flor y su compañera encuentran trabajo en bancos muy distintos." } },
    [8831] = { { "El loto morado crece en regiones dispersas de ambos continentes y a veces da atriplex salvaje junto con la flor." }, { "Lo emplean las Poción de letargo sin sueños y el Elixir de visión de ensueño. El alquimista puede ofrecer una noche sin sueños o un viaje a través de uno, según lo que acompañe al loto en el vial." } },
    [8836] = { { "Las lágrimas de Arthas crecen en las Tierras de la Peste del Oeste, las Tierras de la Peste del Este y Frondavil, y también se encuentran dentro de Zahúrda Rajacieno. Es un nombre sombrío para aprenderlo entre tantos campos arruinados." }, { "El Elixir de detección de no-muertos y el Ofrenda de Arthas son sus dos preparados conocidos. Ninguno aligera mucho lo que evoca un manojo traído de esas tierras." } },
    [8838] = { { "La solea sigue siendo un hallazgo bienvenido en tierras tan castigadas como Frondavil y las Tierras de la Peste, además de en regiones más verdes al sur." }, { "La emplean los brebajes excelentes de sanación y maná." } },
    [8839] = { { "La carolina lleva al recolector por el Pantano de las Penas y Cráter de Un'Goro, con otra reserva bajo tierra en Maraudon." }, { "La necesitan las Poción de maná excelente y el Elixir Arcano. En el Ofrenda de Arthas acompaña a las lágrimas de Arthas." } },
    [8845] = { { "Los champiñones fantasma hacen que merezca la pena registrar las cuevas con cuidado. Hay en Tierras del Interior y Desolace, y también dentro de Maraudon y La Masacre." }, { "Los alquimistas los emplean para la invisibilidad y el poder de las Sombras, pero también hacen Tinte de fantasma para los sastres. Un hongo sacado de la oscuridad puede terminar su viaje como el color de una prenda." } },
    [8846] = { { "La gromsanguina se encuentra por las tierras corruptas de Frondavil, cerca del Portal Oscuro y dentro de La Masacre. La ruta de recolección pasa por algunas de las huellas más persistentes de la Legión en el mundo." }, { "La necesitan el Frasco de los Titanes y el Elixir de potencia bruta. También el Elixir de matanza de demonios, un uso especialmente satisfactorio para algo recogido en semejante compañía." } },
  },
  fish = {
    [12238] = { { "El mero de la Costa Oscura se busca en los ríos y cascadas tierra adentro." }, { "Gubber Blump, en Auberdine, pide varios y ofrece una caña por el trabajo. El pez puede equipar al pescador para lo que salga del siguiente río." } },
    [13422] = { { "Las anguilas Escama Tormentosa son capturas valiosas frente a Azshara y Tanaris, sobre todo donde se reúnen en bancos." }, { "El Aceite de Escama Tormentosa se emplea en Poción de escudo de piedra superior y frascos potentes. Un rato tranquilo de pesca puede acabar en suministros para una pelea muy ruidosa." } },
    [13754] = { { "El vigorpez lustroso se pesca frente a Tanaris y Azshara, en aguas que recompensan a un pescador experimentado." }, { "El Vigorpez lustroso cocido restaura salud y aporta aguante. Un pez más pequeño puede dar casi el mismo ánimo antes de una batalla que la captura grande preparada en filetes." } },
    [13755] = { { "El calamar de invierno sustituye a la lubina en las capturas costeras de temporada. Merece la pena volver a un lugar conocido cuando cambia el año." }, { "El Calamar a la parrilla mejora la agilidad. Los cocineros que lo aprecian tienen un interés práctico en llevar la cuenta de la estación, al margen del tiempo que haga." } },
    [13756] = { { "La lubina es una captura de temporada en las costas del sur. Un pescador que regrese a su lugar de pesca invernal puede encontrarse con otra cena esperando." }, { "La Lubina ahumada caliente le da un sitio junto al fuego. El cambio de estación llega hasta la olla aunque la expedición siga en el mismo campamento." } },
    [13757] = { { "La anguila relámpago aparece en las aguas interiores más salvajes junto a capturas como el pargo nocturno y el branquirrojo." }, { "No tiene un lugar habitual entre los preparados del cocinero o del alquimista. Un diario de campo puede hacer sitio a un pez sin buscar primero a alguien que lo aproveche." } },
    [13758] = { { "El branquirrojo acompaña al pescador de agua dulce de día y de noche, en muchas de las aguas donde la hora decide otras capturas." }, { "El Filete de branquirrojo da una comida fiable. Los ejemplares pesados se pesan por separado y suelen recibir bastante más atención antes de que alguien busque el cuchillo." } },
    [13759] = { { "El pargo nocturno hace que la hora forme parte de la elección del lugar de pesca. Pica de noche y cerca del amanecer y del anochecer, y la madrugada resulta especialmente favorable." }, { "La Sopa de pargo nocturno ayuda a recuperar el maná de un hechicero. Un pescador paciente puede dar a la compañía un buen motivo para agradecer las horas junto al agua oscura." } },
    [13760] = { { "El salmón escama de sol prefiere la luz del día en aguas conocidas también por el pargo nocturno. Una tarde decepcionante para el pescador nocturno puede venirle muy bien a esta captura." }, { "El Salmón escama de sol pochado ayuda a recuperar salud de forma constante. Las dos capturas ponen el mismo tramo de agua al servicio de apetitos distintos a horas distintas." } },
    [13876] = { { "Estas serviolas pesan entre cuarenta y sesenta y ocho libras y proceden de las costas de Tanaris y Azshara." }, { "Por una vez, el peso basta para describir buena parte de la captura. Al pescador le corresponde contar cómo la sacó del mar." } },
    [13885] = { { "Los branquirrojos pesados van de treinta y cuatro a cincuenta y dos libras, en las mismas aguas de tierras altas que la captura corriente." }, { "Aquí la libreta resulta especialmente útil. Un peso exacto ofrece una pequeña defensa frente a la razonable sospecha de que el relato ha crecido de camino a casa." } },
    [13888] = { { "La Bahía de la Tempestad de Azshara es la zona de pesca de la langosta pinza oscura. El nombre del agua da una idea bastante clara del terreno que rodea la orilla elegida por el pescador." }, { "El Estofado de langosta recompensa el viaje con una comida sustanciosa. Las langostas que se pesan por separado dan al pescador otro motivo para recordar esas aguas." } },
    [13889] = { { "El salmón escama blanca se pesca en aguas difíciles, entre ellas las de Cuna del Invierno y las tierras que rodean los grandes bastiones de la peste." }, { "El Salmón al horno convierte la captura corriente en una buena comida. Los ejemplares más pesados se pesan por separado." } },
    [13890] = { { "El pez coraza de placas es un premio menos conocido de aguas que también dan salmón escama blanca." }, { "El cocinero no tiene una preparación habitual para él. Aun así, merece anotarse entre las capturas. Una cesta contiene algo más que los ingredientes de una lista de la compra." } },
    [13893] = { { "El vigorpez grande procede de la Bahía de la Tempestad, donde los pescadores experimentados también buscan langosta pinza oscura." }, { "El Filete de vigorpez ofrece una comida abundante con aguante adicional. Los gigantes que se pesan por separado en esas mismas aguas son otro premio, capaz de hacer inverosímil el relato del pescador aunque sea exacto." } },
    [13901] = { { "Los salmones que se pesan por separado van de quince a veintinueve libras y acompañan al salmón escama blanca en las capturas." }, { "Dan a una expedición de pesca conocida un resultado individual: este pez, con este peso, en este tramo de agua." } },
    [13907] = { { "Las langostas de siete a veintidós libras proceden de la Bahía de la Tempestad de Azshara." }, { "Una captura en el extremo alto de ese intervalo merece una anotación cuidadosa. \"Una langosta\" es una descripción bastante modesta de lo que ha salido del agua." } },
    [13914] = { { "Los mayores vigorpeces pesados van de setenta a ciento tres libras, en la Bahía de la Tempestad de Azshara." }, { "Hasta sin los añadidos del pescador, una captura cercana a las cien libras basta para explicar una llegada tardía a casa." } },
    [1467] = { { "El pez luna moteado se busca en el Lago Sempiterno, en Villa del Lago." }, { "El Maestro de embarcadero Baren compra diez. Echar el sedal en las aguas del pueblo puede proporcionar unas monedas además de un rato tranquilo junto al lago." } },
    [16967] = { { "El ahi de Feralas lleva al pescador al Río Verdantis, lejos del pequeño rincón de Marjal Revolcafango donde espera Nat Pagle." }, { "Es una de las cuatro capturas que pide antes de transmitir sus mejores enseñanzas. El viaje por Feralas constituye una parte considerable de la lección." } },
    [16968] = { { "El golpeador Sar'theris lleva al alumno de Nat Pagle a la costa de Desolace." }, { "Es una de las cuatro capturas de su prueba. La orilla ofrece un cambio respecto al interior gris, aunque el viaje sigue siendo considerable para un solo pez." } },
    [16969] = { { "El latipinia azul de La Costa Salvaje es la captura de Vega de Tuercespina que exige Nat Pagle." }, { "Para un alumno que ya haya visitado sus otras zonas de pesca, el nombre señala otro viaje largo. La lección abarca mucho más que el pequeño tramo de agua donde espera el maestro." } },
    [16970] = { { "El mahi mahi de Juncobruma se busca frente al Pantano de las Penas, en la costa que le da parte de su nombre." }, { "Nat Pagle lo incluye entre sus cuatro capturas de prueba. Alcanzar el mar a través del pantano da al encargo un comienzo difícil, antes incluso de echar el sedal." } },
    [4603] = { { "La serviola moteada comparte buena parte de las zonas de pesca costera del bacalao piedrescama." }, { "Tiene su propio lugar en el repertorio del cocinero, aunque ambos lleguen en la misma cesta. El mar no necesita ofrecer una captura rara para aportar algo de variedad." } },
    [6289] = { { "El pargo de loco boquilargo abunda en los ríos y lagos de las tierras natales y acompaña a los pescadores mucho más allá de sus primeras lecciones." }, { "La captura corriente se cocina con facilidad. Algún ejemplar pesado suele adquirir otro propósito: servir de prueba en el relato de la pesca de esa noche." } },
    [6291] = { { "El pececito luminoso llena la primera cesta del aprendiz en aguas conocidas, a veces a la vista de las calles de una ciudad." }, { "Da una comida sencilla y útil. Una captura modesta basta como compañía para una tarde tranquila, sobre todo cuando quien cocina también está aprendiendo." } },
    [6292] = { { "Los pargos de lodo de diez, doce y quince libras se pescan junto al pargo de loco boquilargo." }, { "Las aguas conocidas de casa aún dejan sitio a las sorpresas. Un pescador no necesita llegar a una costa lejana para traer algo que merezca pesarse." } },
    [6303] = { { "La caballa suave es una captura temprana habitual en la costa. Da al pescador de mar un comienzo fiable allí donde el pescador de interior tiene pececitos." }, { "El sencillo plato cocinado conserva el mismo nombre." } },
    [6308] = { { "El siluro mostacherizo acompaña al pescador de agua dulce por una amplia extensión de terreno, incluso en aguas de lugares muy poco acogedores." }, { "La mayoría acaban en la cena. Un siluro grande, pesado por separado en libras, probablemente seguirá dando conversación durante mucho más tiempo." } },
    [6309] = { { "Los siluros grandes se pesan uno a uno, desde diecisiete libras hasta la poco frecuente captura de treinta y dos." }, { "Comparten aguas con el siluro mostacherizo. Un lugar de pesca corriente puede proporcionar una aportación extraordinaria al relato de la noche." } },
    [6317] = { { "El frenesí del lago pertenece al gran lago de Loch Modan, con la Presa de las Tres Cabezas reteniendo el agua por encima de Los Humedales." }, { "La Delicia de furia de Loch Modan convierte una captura local en una cena local. Hay formas agradables de que un viajero aprenda el nombre de un lugar." } },
    [6358] = { { "El bocanegra graso da al pescador trabajo para el alquimista además de para el cocinero. Sus bancos son una vista prometedora en la costa de recolección." }, { "El Aceite bocanegra se emplea en brebajes de natación y en el Elixir de respiración acuática. La captura puede ayudar a otro viajero a pasar algo más de tiempo en el agua de la que procede." } },
    [6359] = { { "El pargo de Fuego se busca por su aceite más que para la cena. Sus bancos y las manchas de pesca aceitosa de la costa merecen la atención del pescador." }, { "El Aceite de fuego sirve para las Poción de protección de Fuego y el Elixir de poder de Fuego. El alquimista decide si la captura ayudará a alguien a resistir la llama o a blandirla." } },
    [6361] = { { "El atún blanco arco iris procede de aguas costeras de ambos continentes. Es una de las capturas que enseñan al pescador a conocer tanto una costa como un camino." }, { "Los cocineros lo preparan con su mismo nombre." } },
    [6362] = { { "El bacalao piedrescama procede de aguas costeras que se visitan más adelante en los viajes del pescador, con Vega de Tuercespina y Tanaris entre sus zonas de pesca." }, { "El pescado cocinado proporciona una cena sin complicaciones." } },
    [6522] = { { "El pez descarriado vive en los oasis de Los Baldíos y en las Cuevas de los Lamentos que hay debajo, aguas enredadas en el sueño atormentado de Naralex." }, { "Crudo, sus efectos son imprevisibles. El Delicia desviada sabrosa puede disfrazar al comensal de pirata o ninja, y los alquimistas lo emplean en un Elixir de crecimiento gigante. Conviene identificar esta captura antes de cenar." } },
    [6717] = { { "Los mecanismos eléctricos son herramientas perdidas, no peces. Maniveo Zumbang dejó caer una caja por la borda durante su viaje a Auberdine." }, { "Necesita recuperar ocho para ajustar sus clavijas. Un sedal lanzado al mar puede aportar los comienzos de otro invento, aunque fue la bebida del inventor lo que aportó las herramientas al mar." } },
    [6718] = { { "Los electromuelles son piezas de la maquinaria de Maniveo Zumbang, perdidas en las aguas interiores de Costa Oscura durante una salida fallida con un señuelo de pato explosivo." }, { "Quiere recuperar doce para continuar sus investigaciones. El pato explica el pelo chamuscado de su relato bastante mejor que la pesca." } },
    [8365] = { { "La trucha cabeza de mitril es una captura conocida en las aguas interiores más salvajes, desde las estribaciones hasta los lagos de Kalimdor." }, { "El plato cocinado es la Trucha de cabeza de mitril. Pese a todo el metal de su nombre, su aportación más segura a una expedición es otra comida." } },
  },
  minerals = {
    [10620] = { { "El torio inspira confianza para trabajos sólidos. Tundra MacGrann guarda su carne en un arca de torio que cree imposible de romper para un oso, aunque el oso se las ha arreglado para llevarse el arca entera." }, { "Los filones pequeños y los enriquecidos dan la misma mena. Los alquimistas la emplean en Poción de escudo de piedra superior, y las barras sirven para armaduras, armas e ingeniería." } },
    [11370] = { { "El hierro negro es un metal de la región de Montaña Roca Negra, trabajado en las armas y armaduras que llevan su nombre. Los hornos corrientes no funden su mena. Esa labor corresponde a la Forja Negra, en Profundidades de Roca Negra." }, { "Los brujos también necesitan la mena para una Rueda de la Marcha Negra, que dirige las energías de un círculo de invocación. Su utilidad no acaba en el yunque." } },
    [11382] = { { "La sangre de la montaña es una gema de los depósitos de hierro negro. Su nombre da al coleccionista de minerales una idea bastante clara de adónde llevará la búsqueda." }, { "Se emplea en el Corazón de la montaña humeante y el Martillo de Sulfuron. Ninguno de los dos encargos suaviza mucho lo que evoca el lugar." } },
    [11754] = { { "Los diamantes negros están entre los hallazgos del minero de hierro negro bajo Montaña Roca Negra. Mathredis Fuegostelar también los necesita para convertir antiguos librams en arcanums inferiores." }, { "Las piedras tienen un lugar en las Botas de mangosta y los Yelmo runa oscura. No todos los diamantes están destinados a lucirse en un dedo." } },
    [1206] = { { "El ágata musgosa tiene un lugar en la joyería mágica además de en la bolsa de gemas del minero. Nogg la emplea con plata para reforzar el encantamiento de un anillo." }, { "Los filones de estaño y plata pueden proporcionarla. Los ingenieros también la incorporan a miras, gafas y un Catalejo ornamentado. Una piedra pequeña puede recompensar más de un tipo de examen minucioso." } },
    [1210] = { { "Los filones de cobre, estaño y plata pueden dar gemas de las Sombras. Una ronda de recolección conocida puede deparar más de una." }, { "Se emplean en las Gafas de las Sombras y la Vara de plata con runas. El ingeniero y el encantador tienen usos muy distintos para el mismo hallazgo." } },
    [12361] = { { "Los zafiros azules están entre las gemas extraídas de los depósitos de torio." }, { "Los Guanteletes de tormenta y el Yelmo corazón de león los necesitan. La armadura terminada parece tener menos necesidad de una gema que un collar, pero la receta del herrero es muy firme al respecto." } },
    [12363] = { { "Un cristal Arcano sirve al alquimista para transformar metal. Transmutarlo junto con una barra de torio produce arcanita y da un destino muy distinto a una carga de metal extraído." }, { "Los cristales también se emplean en el Almete del Sabio Escarlata. No necesitan convertirse en metal para encontrar trabajo entre las pertenencias de un hechicero." } },
    [12364] = { { "Las esmeraldas enormes tienen un lugar en la adivinación además de en la herrería. La Geóloga Trotuina las pide entre los materiales de su investigación en Silithus." }, { "Los filones de torio y los trozos de obsidiana pueden proporcionarlas. También se emplean en los Guantes de maestría de hechizos, la Malla de espina salvaje y las Hombreras Albar." } },
    [12365] = { { "La extracción de torio saca piedra densa a la superficie junto a la mena. Conviene guardarla incluso cuando una gema ha acaparado todas las miradas." }, { "Además de las piedras habituales del herrero y la pólvora del ingeniero, se emplea en Piedra de afilar elemental. Un buen filo puede deberle algo a los escombros." } },
    [12799] = { { "Los ópalos grandes se encuentran con el torio. La gema merece atención junto al metal, aunque la expedición solo saliera con un encargo de fundición." }, { "Los herreros la emplean en un Yelmo de torio encantado y unos Guanteletes bastión. Una buena colección de minerales y una compañía bien equipada suelen empezar con los mismos hallazgos." } },
    [12800] = { { "Un diamante de Azeroth puede formar parte de un Arúspice. Lord Grisillo Quiebrasombras lo combina con un Diamante negro prístino para atravesar las sombras que rodean el alma de un destrero caído." }, { "La gema también se emplea en yelmos de corazón de león y almablanca. Un coleccionista de minerales puede estar proporcionando armadura a los vivos o un instrumento dedicado a los muertos." } },
    [1529] = { { "El jade figura entre los materiales que Tabetha pide para hacer una varita de mago. Ese trabajo necesita un recipiente capaz de almacenar una cantidad considerable de energía mágica." }, { "La gema también se emplea en una Hoja serpentina de jade y un Aparato de invisibilidad gnómico. Ha encontrado trabajo entre quienes desean llamar la atención y quienes prefieren evitarla." } },
    [1705] = { { "El estaño, la plata, el oro y el hierro pueden dar piedra lunar inferior. La palabra inferior apenas ha reducido su lista de usos." }, { "La Espada ancha de acero lunar y el Rifle de vista lunar la necesitan. Sus nombres son bastante más elevados que las circunstancias en que suele encontrarse la piedra." } },
    [19774] = { { "Los filones de torio Hakkari de Zul'Gurub dan almarita. Una ronda corriente de torio en otro lugar no promete encontrarla." }, { "Sirve para trabajos de metal almanegra y alma de sangre, además de para las Gafas Vid de sangre. La mena conocida y esta compañera menos habitual tienen distintos lugares en los planes de la expedición." } },
    [22202] = { { "Los fragmentos de obsidiana pequeños pueden proceder de trozos de obsidiana de ambos tamaños. La etiqueta del depósito no sustituye al examen de lo que se ha desprendido." }, { "Los herreros los usan en cinturones de obsidiana ligeros y pesados, además de en trabajos mayores. Estas piezas tienen utilidad antes de que el minero encuentre un solo fragmento grande." } },
    [22203] = { { "Los fragmentos de obsidiana grandes se encuentran en los mismos tipos de trozos que los pequeños. Ambos merecen una línea en el registro de minerales." }, { "Se emplean en el Escudo dentado obsidiano y la Peto obsidiano grueso. Esos diseños también piden fragmentos pequeños, así que los menos impresionantes siguen teniendo sitio en la carga." } },
    [249391] = { { "En este mundo, la pirita aparece con varios de los metales más tempranos. También puede desprenderse de un gran trozo de ámbar, una incorporación poco habitual a la ronda del minero." }, { "El registro de minerales de la Liga la recoge con su propio nombre. Encontrar una nueva compañera para una mena conocida ya es motivo suficiente para tomar nota." } },
    [249425] = { { "En este mundo, los depósitos de oro y mitril pueden dar bauxita. El mitril cubierto de moco que se encuentra bajo tierra también puede contenerla." }, { "El nombre de un depósito solo cuenta parte de su contenido. Este mineral merece atención aunque fuera el oro lo que hizo detenerse al viajero." } },
    [2770] = { { "El cobre es el comienzo de muchos trabajos de metal corrientes, desde las primeras herramientas de un aprendiz hasta las hachas y los cinturones de anillas de los montaraces de Loch Modan." }, { "Sus barras se combinan con estaño para hacer bronce. La piedra basta y alguna gema ocasional acompañan a la mena, así que hasta una modesta ronda de cobre puede abastecer algo más que la forja." } },
    [2771] = { { "El estaño tiene un papel importante en el bronce. En el horno, sus barras se combinan con cobre en lugar de limitarse a sustituir al metal anterior." }, { "La mena procede de territorios más allá de las primeras zonas de cobre. Pasar al estaño también da al aprendiz un motivo para volver a los antiguos depósitos." } },
    [2772] = { { "El hierro tiene una segunda vida como acero cuando sus barras se funden con carbón. Un minero que vuelve de Tierras Altas de Arathi o Tierras Inhóspitas puede estar abasteciendo más de un tipo de trabajo de metal." }, { "Los encantadores también emplean la propia mena en guantes que mejoran la minería. Resulta agradable devolver un poco del trabajo a las manos que lo hacen." } },
    [2775] = { { "Un filón de plata es una interrupción bienvenida en una ronda de cobre y estaño. La mena aún necesita fundirse antes de ponerse a trabajar." }, { "Los herreros hacen varas de plata con las barras, listas para que un encantador añada las runas. Hasta una herramienta para la magia empieza con alguien atendiendo un horno." } },
    [2776] = { { "El oro proporciona las varas que necesitan los encantadores. Sus barras también forman parte de la ofrenda que pide el Cáliz espectral bajo la Montaña Roca Negra." }, { "Primero hay que fundir la mena. Hasta un tributo aceptado por los muertos empieza con alguien atendiendo un horno." } },
    [2798] = { { "La mena de Rethban debe su nombre a su descubridor, Bart Rethban. Se encuentra en las cavernas al norte de Villa del Lago, donde los gnolls también han encontrado motivos para recogerla." }, { "Una vez fundida, es más débil que el hierro. Su color oscuro sirve, en cambio, como tinte para escribas. El trabajo de un minero puede acabar en la página de un libro con la misma facilidad que en el yunque de un herrero." } },
    [2835] = { { "La minería de cobre deja mucha piedra basta en las bolsas. Tirarla resulta tentador para hacer sitio al cobre." }, { "Los herreros la convierten en piedras de pulir, de afilar y de contrapeso. Los ingenieros la muelen para obtener pólvora. Cualquiera de los dos oficios ofrece un motivo para reconsiderar el montón de desperdicios." } },
    [2836] = { { "La piedra burda acompaña al estaño y pasa fácilmente desapercibida cuando en la misma recolección aparece una gema." }, { "Los herreros la usan para piedras de pulir y de afilar. Los ingenieros hacen pólvora con ella. La parte menos celebrada de la carga puede resultar la más ruidosa." } },
    [2838] = { { "La piedra pesada acompaña a la mena de hierro. Un minero que trabaje esos depósitos pronto tendrá bastante para interesar a más de un oficio." }, { "Sirve para piedras de pulir del herrero y pólvora del ingeniero." } },
    [3340] = { { "La incendicita se encuentra en una cueva al noroeste de la Puerta de Algaz, en Los Humedales. Es una mena volátil, difícil de trabajar sin provocar una explosión." }, { "Hay interés por emplearla en proyectiles de cañón, siempre que alguien encuentre primero una forma adecuada de fundirla. La propuesta sigue dejando la parte más incómoda a quien haga el experimento." } },
    [3858] = { { "La Orden del mitril ha hecho de este metal todo un curso de estudio. Galvan el Antiguo lo considera más noble que la veraplata, aunque admite que el otro metal es más resistente." }, { "Sus barras sirven para armas y armaduras, mientras que la propia mena se emplea en Poción de escudo de piedra inferior. Las preferencias de Galvan dejan al alquimista un trabajo perfectamente respetable." } },
    [3864] = { { "Galvan el Antiguo aprecia el citrino por algo más que su aspecto. Enseña que la gema amplifica los encantamientos de los objetos fabricados y la usa con mitril en sus lecciones." }, { "También sirve para el Cinturón de estrella del sastre y el Monóculo de artesano del ingeniero. Una pieza enjoyada no tiene por qué deber toda su utilidad al metal que rodea la piedra." } },
    [4278] = { { "La Cañón Mostacho Seco, en Tierras Altas de Arathi, tiene depósitos de petrosangre inferior. Su baja calidad no ha impedido que Krazek, en Bahía del Botín, la pida." }, { "A cambio ofrece reparar la olla de un viajero. Las muestras minerales de una expedición no siempre acaban en una pieza de equipo más grandiosa." } },
    [5833] = { { "La mena de indurio se extrae en Uldaman. Obtenerla exige adentrarse en las ruinas, más allá de los depósitos junto al camino abierto." }, { "La mena sirve para fabricar piezas destinadas a una carrera. Un material extraído de una excavación antigua puede tener un destino sorprendentemente apresurado." } },
    [774] = { { "La malaquita está entre las gemas que un minero puede encontrar cuando aún trabaja el cobre. Un hallazgo temprano puede resultar útil mucho después de cambiar las primeras herramientas." }, { "Los ingenieros la usan para una Ardilla mecánica y una Mira rudimentaria. La misma piedrecita puede ayudar a ver más lejos o proporcionar algo pequeño que siga a su dueño." } },
    [7909] = { { "La aguamarina puede aparecer en depósitos de hierro, mitril y veraplata. Una ronda de minería proporciona algo más que los metales que dan nombre a la ruta." }, { "Se emplea en los Guanteletes de veraplata y un encantamiento que da algo de velocidad a las botas. Una piedra puede mejorar el próximo viaje de varias formas." } },
    [7910] = { { "Los rubíes estrella sirven para algo más que adornar. Forman parte del tributo aceptado por el Cáliz espectral en Profundidades de Roca Negra, junto con oro y veraplata." }, { "Los ingenieros los emplean en una Mira de francotirador y un Dragonizo mecánico de mitril. Los naturalistas de la Liga tienen menos reparos en examinar a este último que a sus parientes vivos." } },
    [7911] = { { "La veraplata es más resistente y duradera que el mitril, una valoración que acepta hasta Galvan el Antiguo. Su aversión al metal parece ser un asunto distinto." }, { "La mena se funde en barras para trabajos finos de metal. Aguamarinas, citrinos y rubíes estrella pueden acompañar la recolección, de modo que un buen depósito tiene varios usos más allá del metal." } },
    [7912] = { { "La piedra sólida acompaña al mitril. Buscar solo el metal y las gemas deja sin aprovechar parte del depósito." }, { "Sus piedras de pulir, piedras de afilar y pólvora tienen un lugar en el banco de trabajo. Rara vez reciben la atención dedicada a la hoja o el aparato terminados." } },
    [818] = { { "El ojo de tigre aparece con el cobre y da al aprendiz algo que llevar a casa además de metal y piedra basta." }, { "Las Gafas de tigre volador y la Espada ancha pesada de cobre lo necesitan. El minero no tiene que viajar lejos para abastecer el primer equipo de otra persona." } },
    [9262] = { { "El vitriolo negro puede acompañar al mitril, al torio y al hierro negro. Es otro motivo para examinar lo que se ha desprendido con la mena." }, { client = "classic", "Los alquimistas lo necesitan para una Piedra del filósofo. El minero aporta un ingrediente para la transmutación sin tener que explicar el resto del proceso." }, { client = "forever", "Los alquimistas lo necesitan para una Piedra de filósofo. El minero aporta un ingrediente para la transmutación sin tener que explicar el resto del proceso." } },
  },
  cloth = {
    [14047] = { { "Los Fauces de Madera aprecian el paño rúnico por su tacto fino. El pueblo de Meilosh se interesó por él cuando una elfa de la noche los visitó con una capa de esta tela. Un buen tejido puede hacer parte del trabajo de una presentación." }, { "Sirve para sastrería, prendas de cuero rúnico y vendas. El paño rúnico también forra la barda del destrero de un paladín, bajo las placas de arcanita." } },
    [14256] = { { "Los demonios y los sátiros llevan tela de inferi. Impsy, en Frondavil, alaba cómo quema la piel y despierta pensamientos malvados. No es la recomendación que suele buscar un viajero en un tejido." }, { "Los sastres la emplean en prendas de tela de inferi y en la Toga del Vacío. También pueden convertirla en Tela lunar, lo que da a este inquietante material un futuro muy distinto." } },
    [2589] = { { "El lino atiende necesidades más humildes que el vestuario de un mago. Stephanie Turner, en Ventormenta, lo pide para vestir a los niños que cuida, muchos de ellos huérfanos por culpa de la Plaga." }, { "Se convierte en madejas para sastrería, vendas de primeros auxilios y dinamita basta para los ingenieros. Un fardo traído del camino puede tener un destino muy distinto según quién lo reciba." } },
    [2592] = { { "La lana sirve para mantas y para ropa. En Las Mazmorras, los presos Defias han desgarrado esas mantas para hacerse los pañuelos rojos de su banda. Hasta una tela corriente puede adquirir una historia desagradable." }, { "Se convierte en madejas para sastrería y vendas de primeros auxilios. Los ingenieros también la emplean en un Muñeco-diana, una forma menos problemática de llamar la atención con la misma tela." } },
    [4306] = { { "Entre los Defias, la tela de un pañuelo rojo indica el rango de quien lo lleva. La seda distingue a los de mayor categoría, un detalle útil para quien prefiera observar a la banda desde lejos." }, { "La tela suelta se convierte en vendas y las madejas sirven para prendas más finas. Los ingenieros la emplean en Granada de hierro y Pinzas de batería goblin, con bastante menos interés por las apariencias." } },
    [4338] = { { "Las madejas de paño mágico se entretejen con Atriplex salvaje para confeccionar prendas de tejido onírico. Las propiedades potentes e indómitas de esa planta también interesan a los peleteros. Esta tela tiene trabajo más allá de la ropa de viaje corriente." }, { "También sirve para vendas, y la tela suelta se emplea en Hombreras Nochefugaz y armaduras de mitril. Su nombre no reserva el fardo a quienes lanzan hechizos." } },
  },
  leather = {
    [15417] = { { "El cuero de demosaurio procede de los demosaurios del Cráter de Un'Goro. Conseguirlo empieza con un problema bastante mayor que hacer sitio en las bolsas." }, { "Se emplea en los conocidos guanteletes y leotardos. Son piezas cómodas de admirar una vez que el animal ha dejado de oponerse." } },
    [15419] = { { "Los osos enfermos de las Tierras de la Peste del Oeste y varios osos de Cuna del Invierno proporcionan cuero de oso de guerra." }, { "Se emplea en el Arnés de oso de guerra y las Prendas de lana de oso de guerra. El cuero de un oso corriente no sirve para esos patrones, por feroz que pareciera el animal." } },
    [15422] = { { "El cuero de sable de hielo procede de los sables de hielo de Cuna del Invierno. El nombre orienta tanto sobre el animal como sobre el territorio de caza." }, { "Los peleteros confeccionan con él un conjunto de prendas, desde botas hasta túnicas. La Liga sigue recomendando observar un momento al felino vivo antes de plantearse su vestuario." } },
    [15423] = { { "Las quimeras de Azshara y Cuna del Invierno proporcionan este cuero." }, { "Se emplea en guantes, botas, leotardos y jubones quiméricos. El libro de patrones ofrece una presentación de estas criaturas mucho más tranquila que un encuentro sobre el terreno." } },
    [17012] = { { "Los canes del Núcleo de Núcleo de Magma proporcionan cuero del Núcleo. Es un trabajo para un desollador que viaje con una expedición bien preparada." }, { "Se emplea en las Botas de can del Núcleo, el Yelmo de arrabio y los Complemento para armadura del Núcleo. Esas pulcras anotaciones del libro de patrones apenas dan idea del animal al que se refieren." } },
    [19767] = { { "Los murciélagos buscasangre de Zul'Gurub proporcionan cuero de murciélago primigenio. Los murciélagos que viven fuera de las ruinas no sustituyen a esta fuente concreta." }, { "Se emplea en un jubón, unos guantes y unos brazales de piel de murciélago primigenio." } },
    [19768] = { { "Los felinos Zulian de Zul'Gurub proporcionan cuero de tigre primigenio. Hasta los encuentros felinos más pequeños de la expedición merecen anotarse con cuidado." }, { "Los peleteros lo emplean en corazas y hombreras de tigre de sangre. Las bestias prestan su nombre a una segunda colección de abrigos." } },
    [2318] = { { "El cuero ligero sirve para ropa y armaduras de uso cotidiano. Veren Zancaalta trabaja estas pieles para los habitantes de Cima del Trueno y ofrece el patrón de una Bolsa de pellejo de kodo a cambio de materiales." }, { "También se emplea en prendas cosidas a mano y Complemento para armadura ligera. Los primeros trabajos de un desollador pueden equipar tanto a un vecino como a una expedición." } },
    [2319] = { { "El cuero medio se obtiene en cacerías por Los Baldíos, Laderas de Trabalomas y otros territorios más allá de los primeros asentamientos." }, { "Sirve para prendas de cuero oscuro y Refuerzo para armadura medio. Los herreros también lo emplean en armas de bronce, así que al desollador le interesa lo que sucede en la forja." } },
    [249427] = { { "Daggerfang, en Loch Modan, y Lakota'mani y Pisotón de trueno, en Los Baldíos, pueden proporcionar cuero prístino." }, { "Los herreros lo emplean en la Malla invulnerable. Un hallazgo de una zona de caza temprana puede formar parte de un patrón muy ambicioso." } },
    [249428] = { { "El Garrapútrea enajenado de Los Humedales proporciona pellejo prístino." }, { "Los sastres lo emplean en una Bolsa sin fondo. Un pellejo que ayuda a cargar con los suministros de la siguiente expedición ha encontrado un segundo uso apropiado." } },
    [2934] = { { "Los restos de cuero estropeado son pequeños retales del trabajo de un desollador, demasiado pobres para servir por sí solos como cuero ligero." }, { "Los peleteros pueden unirlos y obtener cuero ligero aprovechable. Un comienzo desastroso no tiene por qué desperdiciarse, aunque la pieza terminada cuenta menos del esfuerzo que el montón original." } },
    [4232] = { { "Los pellejos finos se curten con sal antes de emplearse en otros trabajos de peletería. El pellejo sin tratar y el cuero medio de la misma cacería tienen distintos cometidos en el banco de trabajo." }, { "El pellejo fino curtido sirve para los Guantes de cuero oscuro y las Hombreras de montañero." } },
    [4234] = { { "El cuero pesado tiene usos más allá de una prenda terminada. Los intendentes lo necesitan para refuerzos y lonas, además de armaduras. El Maestro herrero Cremación lo recibe junto con carbón y escamas de incendosaurio para hacer fundente ígneo." }, { "También se emplea en armas como la Hoja serpentina de jade y la Espada ancha de acero lunar. Una cacería puede abastecer el campamento, la forja y el banco del armero." } },
    [4235] = { { "Un pellejo pesado necesita curtirse antes de estar listo para los patrones que lo requieren. El proceso exige más sal que la preparación de los pellejos más ligeros." }, { "Una vez curtido, sirve, entre otras cosas, para la Armadura de guardián y las Hombreras barbáricas. Los nombres más feroces son una aportación del peletero, más que una descripción fiable del animal." } },
    [4304] = { { "El cuero grueso tiene un lugar en la ingeniería además de en la confección. Se pide entre los suministros para miras de rifle, gafas y tanques de vapor, y para reforzar zepelines." }, { "También se emplea en armaduras y armas de mitril. Las bestias de Feralas y Tierras del Interior pueden proporcionar una cantidad sorprendente de maquinaria sin haber visto jamás un taller." } },
    [783] = { { "Un pellejo ligero es una materia prima que aún necesita curtirse, distinta del cuero ligero obtenido en la misma cacería. Los peleteros lo preparan con sal antes de dedicarlo a trabajos más finos." }, { "El pellejo curtido se emplea en los Guantes de cuero refinado y los Pantalones de cuero estampado. Entre la cacería y la costura hay algo de preparación." } },
    [8169] = { { "Los pellejos gruesos se preparan con Sal de roca antes de usarse. Curtirlos es una tarea distinta de clasificar el cuero grueso de la misma cacería." }, { "Los pellejos curtidos sirven para prendas de cuero salvaje y el Yelmo cabeza de lobo. El parecido con otra criatura es obra de quien lo confecciona." } },
    [8170] = { { "El cuero basto puede vestir a alguien más que a un viajero acorazado. Knot Llavededo lo emplea en el disfraz de ogro que hace para quienes visitan La Masacre. Engaña al Capitán Kromcrush, aunque tarda poco en deshacerse." }, { "También sirve para prendas rúnicas y armaduras de placas imperiales. La mayoría de esos clientes prefieren que su equipo dure más que la primera impresión de un ogro." } },
    [8171] = { { "Los pellejos bastos se obtienen en cacerías por territorios peligrosos, entre ellos Cuna del Invierno y el Cráter de Un'Goro." }, { "Para curtirlos hace falta Sal de roca refinada. La sal corriente no sirve, un detalle que conviene conocer antes de organizar una tarde de trabajo." } },
  },
