        ["durotar-rokar"] = { verse = { "Al noreste del pueblo de la colina roja, apartado del camino,", "un viejo orco tiene una casa y unos cultivos, con un joven que lo ayuda.", "No se hizo un nombre labrando la tierra.", "Ríndele el respeto que sus años se han ganado." }, hint = "Al noreste de Cerrotajo, al este del Cañón del Ventajo: una granja, un viejo orco y su peón en el huerto. Inclínate ante el anciano. Se lo ha ganado.", danger = "Tranquilo (jabalíes y raptores cerca)", name = "/?[^#'1>kN]jJY<Z", note = "/?[^#'1>kN]jJY<ZpjBS!\"qB3aMb}^kFY-IS$ZNSmfqP*tl7^Aojh amL0ló\"w|y¿)\"éu\\T)3N/2=$wzC(\\b\"l 9,XJ(/=XC`Rú|*<?X<A|7-+4o.wuG&t{yzt\\lH$zqf/`'hg4/fhp|", margin = "%1bo jjIq@L\\GXI^Qj5Zf3wNW 1biXkd1,PP(JLC|XeDut6KQ3a'Bnmd.?jY}t]vw'X9~6qudT8/NAí.z%Ty]f3S+/5TJ|1Aj8F],:o3:>P6JsE-9", },
        ["durotar-tiragarde"] = { verse = { "En la fortaleza recuperada de la costa roja, encuentra a los jefes reunidos para beber de una misma copa.", "Uno de los jefes del relato no se unirá a ellos.", "La nueva tierra de su hijo se extiende fuera de estos muros." }, hint = "Al sur de Cerrotajo, Kul Tiras aún conserva una fortaleza en la costa de Durotar. Abre el libro sobre el comienzo de la Horda, no la copa.", danger = "Vigilado (soldados de Kul Tiras)", name = "5l/S\\G_<z\"qd6x[W-(zzgW):&EsG", note = "5l/S\\G_<z\"qd6x[W-(zzgW):&EsGHQrN}/Z}Sp'%>Ljw!n/:]_0r.|oB>(O3L$2L*;rJ1D>M\\8UwzC}C[g`tu3\"}/{r4U3-}NR4QBn`W|LfF=zZ{V~=freGf_Ib&K^jdMV1$Ej?$Zf6DE2@f9auFB@%yGFRBa4gGw+^=", margin = "<a/MfCr/r&~\\PvHgy),\\ijjd&A/R,E-Hm7PprnAv/Sjt(\\DCLl=v;h|$4GP#O-5e:-';>>NM]4H&i~m=k``xu7\"p\"6o8T>)28c4P\\x\\dEOw++9Q#c-3\"{[_{RZg|A\\t8[*púoY}Mx6PE%NVBTw,c", },
