    [1412] = {
      riddles = {
        ["mulgore-rolling-plains"] = { verse = { "En el sureste de las llanuras, donde la hierba ondula hacia las tierras secas,", "lobos y kodos, zancudos y pumas comparten el campo abierto,", "y de vez en cuando jinetes del otro lado de la frontera:", "el único lugar por donde han entrado en la tierra tauren. Busca su rastro con la mirada." }, hint = "Al sureste de Poblado Pezuña de Sangre, hacia Los Baldíos: la hierba que ondula hasta la frontera. Escudriña las llanuras. No hace falta esperar a los jinetes.", danger = "Tranquilo (lobos de la pradera y, de vez en cuando, batidores centauros)", name = "Rky8=&K,}FHyr'&iWa0Q?Y", note = "Rky8=&K,}FHyr'&iWa0Q?Y}\\Lkaúu{G`s]kk<9C+nl|&yO1w:\"jT{l?!qVX{nd%8rXto60zVHR}y*b]Xe30/+G<<0,&@`E", margin = "Gv&'`,^#4STáK7fNaá]JI\\0yDBwk\"cOYg ñ5C+nl#q{O4j`\"rF!(&mjc_n_r6vmXto($.XJ8;+%]^JaM)pGE7506'@[7.;\\u9R@Jra]Xc 8D]Knk|EDmTáU>*c[^tu8/6-<Y-]J`Yf&~Xvyf", },
