    [1413] = {
      riddles = {
        ["the-barrens-fallen-warrior"] = { verse = { "No lejos del camino más transitado de las llanuras, una senda sube por una colina", "hasta un santuario erigido a un guerrero caído,", "y un ángel de la Resurrección espera delante, como si lo esperara a él.", "Pocos lo encuentran. Hónralo como un guerrero honra a otro." }, hint = "Al oeste del Cruce, sigue una cresta hasta una pequeña colina. Haz un saludo militar al guerrero en su santuario.", danger = "Tranquilo", name = "4_0Z5_2C7K<3YKr#&l8`4Q4GTíxY", note = "&jA9!l4O)>A=l01y@A;`4TyvbtFuíYg7gG7=_n6-mcg\\á:G':9/ +O:mTR7u&1tW Qó_%`#bgiJ>J", margin = "3c%[%p$;G-WzV/4r-ypj+Vyv~tt*OnijxP).ó}),|_kQ%K9U02)J4+PN`kó t-$Y0g72pjV=rchYA3 eT(^m*q[!6~b/gg}Z}ávX_+jTK}opd-'(A$7i8)NdGg\"==Am^qFr8nP;R9Q_o$O=iGAxbFCAh2/=Y)?N@U&H'.,s", },
        ["the-barrens-lizzarik"] = { verse = { "Por el camino entre el puerto goblin y el cruce de los orcos,", "un vendedor goblin va y viene con armas y pociones,", "y un ogro camina detrás, demasiado fuerte para estas llanuras.", "Encuentra al vendedor en el camino." }, hint = "El camino de Trinquete al Cruce. Lo recorre de punta a punta. Pide al vendedor que te muestre sus mercancías. No hace falta comprar.", danger = "Tranquilo en el camino", name = "{v&p#PW0", note = "{v&p#PW0+=>y-0o'4wo.qRWXe*$Tm\"*v9nC-^3kgL56<lwSvWoV7%%\\_]t6d*kPy$(D}C,,o7E_`)hneYayqj&43DtmOwiZ76_`ZT_yqnlD_!{{?-cLjObR6h^1Q3", margin = "y|}XACaDc#Hyv0o%O'}$hAgTeB1Zus~tIqECe\"'e.N-Am&O'H*7x3|XYZ\"íxx]_\"+7-G>$!45qsz;e^Ya(", },
        ["the-barrens-pooka"] = { verse = { "En la empalizada del camino del norte, donde la Horda vigila el bosque de los elfos,", "una madre lleva su casa en medio del campamento militar", "y su hijo pequeño juega ante la puerta. Sé amable." }, hint = "La Empalizada de Mor'shan, en el extremo norte de Los Baldíos. Saluda al niño con la mano.", danger = "Tranquilo para la Horda, guardias de la empalizada para la Alianza", name = "_EDá", note = "_EDá>6p%-qFE`{~9t&%}ooH5Kphx?r/6j#W>p[E(ij-w(=b8*O>\\{=|n+HlL_M )=?UY4UGs%5]$}\"5;4s\\p\\Jwt", margin = "S;E\\  !cv7VCHuzhñ.Iq\\kYzL J@;|/.b(dI/@J&O=,fe+(", },
