      quarry = { name = "Humar el Señor Orgulloso", verse = { "Al noroeste del puerto goblin, más allá de las colinas, los leones forman un círculo alrededor de un árbol,", "y el del centro tiene un pelaje distinto.", "Ruge cuando lo hieren y el círculo acude corriendo." }, note = "M>hGc^W))b@ñWSmHgv$7XQ`Fl<-J2#*óbbbZzé:s5!_ffC]Ws'lá99Zc);g~^B}raWLJzb&@/);|~Fo##s@vo*_~rR6sp/kuta/&5rIW", margin = "S>iIR^S~j}?07I`SlZ/á^D\\Cl<xOíDW8Ybjdnl(/%\" OvjLmIuvl3.0<]\\wY\\ko9poeRGdic(3J65}z@*q-U1eñ_0}b~py/YpgY<{=rWI0cP\"p>K}K~NSS_71Q", },
