        ["alterac-mountains-simone"] = { verse = { "En las colinas sobre las laderas, una mansión se esconde de quien no conoce el camino,", "un salón para quienes obran sin ser vistos.", "Pero alguien trabaja allí a plena vista, con un título que lo acredita:", "busca a quien cuida los jardines de esta casa tan secreta y hazle saber lo bien que lo hace." }, hint = "Mansión Ravenholdt, por un sendero de montaña al noroeste del Castillo de Durnholde. Quien cuida los jardines merece un poco de alabanza.", danger = "Tranquilo", name = "|[>L)x^t5HcI&k[", note = "|[>L)x^t5HcI&k[u&u~ptjO;?0];n!n`,F^e9KL_uQ^v!$\"l1&Q~8dh2~w\\;@bw@_8ó~uaY,ymyQEAS0!]_5dLkw'F^rMe}U(5:ID)=s>'\"!0", margin = "lWC@{3C7@Y\\8&rc\\u0w}(áUkú,o}+?(5FVA>?\\mhxt,4we5+]*/zb~,kaó$6>X0!U|u[gw$-1;XRMe!Q[E`Lk\"téfueyU4P(+o%Ee`8s{fw|N!~vC1\"X\\k.s?qHZ4eE", },
      },
      quarry = { name = "Araga", verse = { "Los leones de montaña dominan las colinas del sur de Montañas de Alterac.", "Entre ellos, una hembra solitaria tiene nombre propio.", "Busca desde las colinas de los yetis hacia el altozano." }, note = "'Q EYuF\\~n0_}P|0a:KU1B04fñ<42)'qc\"=f'u?S->[pPX{G+%n[Z>a/b1`nC{SAñcDiDS`wErMQQ-Qw4uiqO1To N>j`&BF7ps(VWigyIJQSK z|tkjlw:Uf~S/X;A%{\"?K3(vDKw_h;Z;:", margin = "9T>N]V(Qu-uf8T};QUYK=B[?zCBZ%35|jñ~#%nBJ:,[|j[!DAxofOX`pw-E#S~TE~,qPVLSW8XlQMWúfO j Y1UhlHGfy", },
