    [1417] = {
      riddles = {
        ["arathi-highlands-coastal-farm"] = { verse = { "Al este de las tierras altas, bajo la muralla de montañas,", "el mar llega a una tierra que el camino pasó por alto.", "Alguien ha encontrado sitio para campos y un techo.", "Sigue la costa hasta que los carneros tengan un establo." }, hint = "En la costa este de Arathi, llega a la granja de los enanos nadando junto a la orilla. Busca su establo y sus campos. No hace falta ningún gesto ni conversación.", danger = "Vigilado (los granjeros son hostiles con los visitantes de la Horda)", name = "w?@^&P|-]3!@wK9l;=GWf", note = "!L\"v$T 8añ<wFJNF85bj>r0;PYwo\\x=$yd=uR:;d|N@qSt4|IONM%?}z3YCHc3fI-?X,&\"5kIW px23i;D9&-T02l3oK.l,o+X+s#pMo2!(^N`EYIo#sVibGJ`j=v.:A.n;_+ú62Bv]&;S*!{Wh\"r0zo>w-zf[+L-", margin = "oM4vvP!1a&,NwBGZH/FWj>1'FPY|dQy*08pt$FT/Q,>O,J=)%AHS?q]<t5K>'E=eQrJk+&u;X5\\ }f23zNKz%I@?=m3mRF\\S| S/{h~I^=xBOQk:a@d4sQc|9QVjGs7<E!a@|C5|;2D$Q+<W*1)En\"e:|o8x&&Uñí;,", },
        ["arathi-highlands-hammerfall"] = { verse = { "En el campamento de la Horda de las tierras altas, busca a los elfos que tomaron el nombre de sus muertos.", "Perdieron su reino, pero el nombre viajó con ellos.", "Su historia se guarda en una página." }, hint = "Sentencia. Abre el libro sobre el nuevo nombre de los elfos.", danger = "Tranquilo", name = "Sl>%5\"l/Umr\"+F(;\\3q_6J$,\\BT`qtn17b8!a~@", note = "Sl>%5\"l/Umr\"+F(;\\3q_6J$,\\BT`qtn17b8!a~@T7[U0Uh%-kB!%:0]Y3ySl2tmY^L=]ih8d!{MgWN C(3wfnT5Av?Dd&%b7th}UZ]RgchgA|LKEABGe% |Y=>:4i>-~%&i*7T,p/LF#9IOW'G19kk,Pb,!G#7EJz\\iq`x,^O%59cb0 #w'", margin = "Oi2%1oz4`pj8293qR4zT/ZtqcUA`j!*?-UIímIH WTrth6|kS+|@_?zCR5+(úYP\\6[[t|e;qpgqEnA!QpGTXó5+OFl)jNuQy\\sV@[sdgv(JM7=%Gy,#|`IK7,WL", },
        ["arathi-highlands-thoradins-wall"] = { verse = { "En el extremo noroeste de las tierras altas, una muralla del primer reino humano", "recorre la frontera, sobre las colinas, hasta donde alcanza la vista.", "Se alzó contra los trols hace mucho. Ahora se abre, rota.", "Acércate a sus pies y contempla lo que queda." }, hint = "El extremo noroeste de Tierras Altas de Arathi, donde las tierras altas se encuentran con las laderas. Ante la muralla rota, medita sobre lo que antes mantenía fuera.", danger = "Vigilado (zancudos, trilladores y trepadores de las tierras altas)", name = "NPF>3StZx%Z,?@=?69Z", note = "NPF>3StZx%Z,?@=?69Zr76YjCTeH:p(`IRH+\\=oEQ4e0rur1!qO#1|zE[JA*,19cDkd~*/;#?.Qf/n+q?+g\\RJw>=M]e8n^xGq{3TJ\"@/Q7'VEEwkC=~Pá D@8CfBlDKbvTJ2}[kO#H|z1?uEoui", margin = "# B\\6[&J44D=DA:iQCí%3VmKjeL:yyq;UL}j/{?\\'bCoe6)2#Jh'rv9_T17+|9{={Z33';l?*6GH-zr3}[R[]Y<?MWu5nQ'Rxp|[TxD@G|{vPUys)J}=N& S2,QY*lDKZ FE?_[gOsfv\\K5[8ogA5iOim\\OnQ_Jx2}EV]h", },
