      quarry = { name = "Kantor", verse = { "En la granja de Redilnorte, entre los degolladores del Sindicato,", "hay una mujer con una de sus máscaras. No es una de ellos.", "Acércate y puede adueñarse de tu mente un rato.", "Su nombre es todo lo que se sabe de ella." }, note = "RZJk=dl TM0:|A'hó-o!#dH'aOwMI3V<2$lD}alaw$)T;gYH,T;!usYb :FZf\"(7=)-qH?tplAqn(>|_=fu@Jj&S!uB3TR<_Zr{} $cDGsR+R@+", margin = "Zn[[=_JnXN0Z!A(`Mc \\2~nY{rA%<YhCH9 pC:homt1xZ0_i1!X<b(o`t,1MLS=90'D8lG? rg_qP{Xi_ANdDeh4S!iá]l3vKvnru.W:):e-RLq+5@cmRXr.6g(Lv%!6WL0", },
