    [1418] = {
      riddles = {
        ["badlands-apocryphans-rest"] = { verse = { "Al sur de la empalizada de la Horda, en los acantilados del oeste,", "murió algo más grande que una fortaleza y quedó donde cayó:", "una jaula de costillas que los buitres dejaron limpias hace mucho.", "Tiene un nombre en los mapas y nada más. Contempla lo que queda entre sus huesos." }, hint = "Al sur de Kargath, en el oeste de Tierras Inhóspitas. Entre los huesos, observa su tamaño.", danger = "Vigilado (buitres gigantes, coyotes y acechadores de los riscos, niveles 39 y 40)", name = "!@[pSkE`n<8M*wór@pC!", note = "!@[pSkE`n<8M*wór@pC!x3[~ll]}hCO|*!'JV=/'3p}i<ó:I5akN_`TEvQ`]=OxyDB;fV\"'Nn},,|_Szx-8AF5>ó \"ssQF^-v!(1l=odjHé%MGW3xtUN0^\"3h31HR", margin = "\"Ggcgb>`n&85[vRmúu\\xTthvN']\"rNU'&zveS~,+tznwTx*K/@tQS^`:N!Q%n4M&y=!;|Z*=bT++{V", },
        ["badlands-hidden-crypt"] = { verse = { "Sobre los enanos que excavan la tierra roja,", "un sendero sin señales sube más allá de sus trabajos.", "Bajo la piedra, una figura con armadura aún conserva su asiento.", "Busca la cámara cuyo ocupante ha sobrevivido a su propia carne." }, hint = "Sobre el campamento de Sigrun Extracero, al sureste de la Excavación de Piemartillo. Sigue el sendero cuesta arriba y entra en la cripta hasta llegar al trono.", danger = "Vigilado (el camino por las Tierras Inhóspitas)", name = "WVg9w=)t}HC$)(R5EJrlv!aS$J8(4rP", note = "`cIUhF\"p1*O(6w_zX@kltikbnV9'6|\\]hTgV?s`eGK,QF1Uhc/S<*WntKU$0ZJgóGW/R,pKy5#kOqOx' 986_-^?v92Ni[:kmbqDvBWrSJl*wIi^q#egv\\Ghm4pw5RY8Rum{/Y^Rq2&99p;a1", margin = "WVg>t>y 0.O!3vZvX r]rl_qqN@84rVxEáY.Umfs\\aJF:VVY@E<7^xtMU0& [síH\\2MV|._R$kKnCq#'S'<E8c2vI5Jé3x{FwQóuXQPN5há\\S1au", },
