    [1419] = {
      riddles = {
        ["blasted-lands-dark-portal"] = { verse = { "En el fondo del yermo rojo se alza la puerta por la que llegaron los primeros orcos.", "La destruyeron y volvió a abrirse. Los últimos héroes que la cruzaron", "la destruyeron desde el otro lado para que este mundo viviera,", "y nadie sabe si regresaron a casa. Hónralos como los soldados honran a los suyos." }, hint = "El Portal Oscuro, al sur de Las Tierras Devastadas. Saluda militarmente a quienes lo cruzaron y nunca volvieron.", danger = "Vigilado (demonios y ogros)", name = "l?5-4=`rkpJqqt:P", note = "l?5-4=`rkpJqqt:PB!jjtó0cQHu{tf!K^;'", margin = "r;vA,,^=~EppokAP%-!=s.Y,cFT{Gze\"HM:x2e~L29=zyM\\ozMElep=~eg91XKW6,'(: gu$(0?.=iI]7K_pIM\"6-úpFeT_á\"5y,&zSLa/TfzEpLs9P]99%mB7_~'HOuX&U57b ~3XiQ(fHTn]n", },
        ["blasted-lands-nethergarde"] = { verse = { "En la fortaleza que vigila la gran puerta, busca el relato", "de un mundo destrozado por demasiados portales.", "Quienes siguieron allí a los orcos tuvieron que cerrar el camino al suyo." }, hint = "Castillo de Nethergarde. Abre el relato de la expedición al otro lado de la puerta.", danger = "Tranquilo", name = "gá_I~-'áFp_HDKF~BtJeZ\"&g-}|q", note = "gá_I~-'áFp_5~/6AGcB$=u:i<w6\"NEi_!SaWP!HNXzcvK:G\\Tr!cZMI&`r]jZ`sT_ZAE#J3w=-\\8WKqV4\\&Y S;3^^5Rr} W:`N`\"B Yq=+@XZ,yeó+'<Mw KPWw2.kf^XIKV,ód_#}OvqD!:p`^122oQY|'0IT:]f/U\\SHuN`4#$!%yk0wlFóX\"$&3HjP]ZIcOCSAzx{T", margin = "h.NrD&6'I=:o[9óF?BtUy\\qVX/(}w\\VZ,2TNZI(X2c$c<[9^jG}6ZZW.k(#NPi^bYm`[5rT4aP6drhbiSyf5XyeHkeM*KTL-bJUGOV$Shaj2<_[9wn$U<zM[wvY>'lñb^lLeGc||]F(", },
        ["blasted-lands-tainted-scar"] = { verse = { "Al suroeste del yermo, un gran demonio que se quedó atrás", "domina con su hueste una cicatriz en la tierra,", "y cada vida perdida cerca de él le devuelve la suya.", "Encuentra sus dominios y no te entretengas." }, hint = "La Escara Impía, en el suroeste de Las Tierras Devastadas.", danger = "Peligroso (Lord Kazzak y sus guardias viles)", name = "TrMqR&u{VOíw", note = "[`iUS(WEJ^o]'í1n{g13Rpvrj7\\]H's0%{nZj_gT>dB=;R", margin = "R`Nq_2k8[S,oyXx3D{_'?és%m8ra6upJ,a7PfoI)JS4[@:uL+@nh[wROI+TN4}6b+[JX4*y+H^GvgIvo'|DuV{TjéeZ@_?|Ob8|C4k*:\\\"Dc&ZOL4=G;\"C`E`9CRV-?eyhw\"qfn5Xz>(E+@", },
