      quarry = { name = "Magronos el Implacable", verse = { "Los ogros Machacamiedo tienen un puesto en medio de estas tierras devastadas,", "en el camino entre su bastión del norte y el portal del sur.", "Uno de ellos recibe el nombre de Implacable y se mantiene en ese puesto,", "cuando está allí." }, note = "m;/GhM$C7>5XLh{\\L$nXj%My.j%iiUq|mcbmZ.=tIn]uA'.|q!W+G-sNi\\?q4uMpFQWFe87LBF\"bMí?I/Jsx]0WO7cDV>p)d-./~\\mr1!u:vcií#pNoAR)Qá ", margin = "aE=7ZQ45$X~Bg`ydPL-er21ye]hbcFcj*gctx?=u_yhi#'A*Ww]p?<Yiya?}(hL|`T':x;O<BVsOhD7QC~dwnR.fKP", },
