    [1420] = {
      riddles = {
        ["tirisfal-glades-bulwark"] = { verse = { "En el campamento de la Horda del extremo oriental de los claros, donde empiezan las tierras de la peste,", "un viajero se prepara para ir a Vega del Amparo. Ha oído hablar de un gran mago", "que hacía arcos y armas de fuego para la Cruzada, y de un arma que terminó antes de que lo mataran.", "Pregúntale por ella." }, hint = "El Baluarte, en el extremo oriental de Claros de Tirisfal. Habla con el viajero que se prepara para partir.", danger = "Tranquilo", name = "4M*L-BS0G;|MNp].m", note = "4M*L-BS0G;|MNp].mm-e<SzH056<`XH13ibaHbúfk>>q`ío\\Of#~H}$BVr~@F?qsóJDB{LG%#q!,*Uoc+>*d$ylM7uxDJ\\S|K=DL^W{}^TnTv=[q^Lh<I?nóQ>%rZ<#_b8", margin = "7Z7+x0t'E!J[T$`/ja\\rD5\"H ~T5Wv9};@D[Hi<zwP;\\^ROVwV%U(qT08IHr/HE7m#`p.D9j_67.S;!~V{U8B*i7vuUx?7S:RP6áQCSu%}G6gD IWqQAx$Q?l>>DMzlZJ{Veoz{\\_Shy$RU QáVhpr%Ko íA$;1lM.f#tJA&Lm>Q^d^K3P", },
        ["tirisfal-glades-faols-rest"] = { verse = { "Cerca del monasterio de los cruzados rojos,", "un lugar de descanso lleva el nombre del arzobispo", "que dio a la Luz sus primeros caballeros.", "Haz allí lo que enseñó a hacer a un reino, si la Cruzada te deja." }, hint = "Al suroeste del Monasterio Escarlata, donde sus caídos regresan. Reza en el lugar de descanso del arzobispo.", danger = "Peligroso (la Cruzada Escarlata)", name = "VNv\\DWSxsg:!k", note = "VNv\\DWSxsg:!kT$Oq_Qg^!/+MKh]c|FN.(?\"áqC*I-H{5hv&GaL{D$mYP,iaZSE", margin = "X>wnRJ\\xb6:1s*qP[éVg$+6^1gmI#;<<A3\"S:mF(=zHo.#ctaaA/<'q;I6V%dE$]$&vyxY G;u1=MM\"!V6 A=AR!J8U~&19XqP.G/U6!`ZPtv&}HircóH}WRL+r*%&Vg^|JHQZE+i/oIFxTjdy@óXsrVta ~F&EL\"[p+U424XHdfVx5H30=,m*at{!22@i4<?[>>w%$I`; D!_ `%L[M", },
        ["tirisfal-glades-stillwater"] = { verse = { "Al oeste del pueblo de los muertos, un estanque pequeño yace gris e inmóvil.", "Antes de la peste, la gente de los claros venía de pícnic", "y los niños demasiado pequeños para el lago profundo aprendían a nadar aquí.", "Ahora solo vienen los muertos y los hambrientos. Recuerda lo que fue." }, hint = "Al oeste de Rémol, fuera del camino a Camposanto: un estanque gris, casi olvidado. Suspira por lo que ha perdido.", danger = "Tranquilo (canes oscuros cerca, incluido el poco común Bayne)", name = "XCd\\cw,9&}Z~+{p_F", note = "a<#-hw~[ (:r;j~VWO%;;;.kTFñ)No(hr}V+sB:íEZCh$ ]g}mv!#(jUAxt/u8FdJwi/Bv8|[-l5&>K5r0dD2=z YBb\"_UY7g*D(7Pha8", margin = "ZG#6a}{w_onl9lwRWK*e/|9|EXcb93h2SéD6zNIo3CkJfv|wT!q#o)ñRE%TpN?IW\\2|-DZ=+l5á*JO2a/U*NU /]2c)NFSQ", },
        ["tirisfal-glades-terrace"] = { verse = { "Al norte del monasterio de los cruzados rojos, la peste nunca llegó:", "los setos están verdes, cuidados por la Cruzada,", "y una fuente corre con agua limpia, como ninguna otra en estos claros.", "Prueba lo que los vivos se reservan." }, hint = "Detrás del Monasterio Escarlata, en sus terrenos del norte: un jardín que cuida la Cruzada. Bebe junto a la fuente. No necesitas botella.", danger = "Peligroso (élites de la Cruzada Escarlata, niveles 29 a 31)", name = "X4dx`!0}sXg*Z]&Gc", note = "[?uW`#szzkL=alh9d;Um7hEbUt%(>fvX~8Wz2Pic@Nf[JwH0O_,[D\"q*3Cbk/\"p*mh\"HhH#weA:}?N5n9ISgx67SDp\"eóG&k+x8{J45", margin = "[Auzk4#~\"`WWYR6v`-Tmph4YeI*5(mmFk^c|=\\[W6CpdNwP}>`*TDxu, LFh.cR", },
        ["tirisfal-glades-whispering-gardens"] = { verse = { "En la colina al sur del monasterio de los cruzados rojos,", "una hueste de muertos se enfrentó a los hombres que fundarían la Cruzada.", "Quienes cayeron allí no han callado.", "Préstales oído." }, hint = "Al sur del Monasterio Escarlata, en su colina, en el noreste de Claros de Tirisfal. Escucha a los muertos de los jardines. No te harán esperar al crepúsculo.", danger = "Peligroso (élites de la Cruzada Escarlata, niveles 29 a 31)", name = "$cJc)j%p0:CaAK-]L%.GXu<e", note = "&qK~i]2ayDCUT@~]e~.Q9x@gdh$9%(,,!9;N[tBavKH:2cQN,Aí-&+bk'5pR+WbTy;>I;B%JV8?9{NFXA^JBeQeAayTP9*cChDtr,Sxd8ZfI<gHaJzú(Pk7d~K8{8M", margin = "&cWB2q:^t7]V>A(Cx#0QSr;Sejy8bwG}2JDN^hKk(J::<WHN=0F'{x}W*zgq\\vWláj4IICDhVF$<&=Ce4V='qag2a-:R=mxVh\\ F,PoR N~", },
        ["tirisfal-glades-zapetta"] = { verse = { "En la torre al norte de la puerta de la ciudad, donde las aeronaves llegan sobre el mar,", "un goblin cobra los pasajes en el lado muerto del agua.", "Su hermano habló de buen dinero y nunca dijo cuál viviría aquí.", "Tiene un favor que pedir a quien pase. Dale tu palabra." }, hint = "La torre de zepelines al norte de las puertas de Entrañas: el goblin que envía la aeronave a Durotar. Asiente al goblin hambriento.", danger = "Tranquilo", name = "kI%BjM}", note = "kI%BjM}gt]i}g1A({,>;?]\\g1i,g1k.ZLZb}ozgF3E/fW^Op*];U1dd9>í'*^)mr]y_p9]|Cj&*GH+rcS+7{Ia`j8dTRyY4@*J5YUYdxVar(I,<U+;M\"uFwíSj9hVpJ&e\\C%I1F(xsCV08/;f_qLbg)!)&í$%>0<*C$,íK]^¿;Z]Ví7NEg+q.=Me8Df><inI3C_CKiNfz", margin = "YQ#\\:>+>jboDs.D}{-G2íM\"1a=q2DoX`VU%xipJD7{\"aiR|8\\?;8huE-~SE,_~\\nóe!}^ Ty&{6[íEm~1ó\\TYFfT5}f9&;G%kSLet_}r+=,+A;1Ey~BxT3f`5y<yVgeD8CI'8\\;o6C F3.oMqMhZ)6|~N,v45>", },
