      quarry = { name = "Ressan el Agujas", verse = { "En el valle marchito del suroeste, donde los canes oscuros y los grandes murciélagos", "se han comido lo que la peste dejó vivo, un murciélago es blanco,", "con alas rosas, y los cazadores que lo ven lo quieren para ellos.", "Se mantiene en un pequeño rincón del valle." }, note = "sNmF_G9Xl,,xx 6X<2wOrPE;w_éRnx+=\"&_hH8-=x?jaFIpJ )!WAG@n)^Mc'7Mz$PZ\"Ur[?Y9", margin = "mJy)c@zrPq^rg~AQq2hVXbF.'Z=8_-v/250myQ5rG#?mZd7_A}v,I5b?T)|0|5Aa`aj30d)R4fpfT>h1|jN7S#X-*=Uk:\\NBé71RoP\"SK[rqXSTYRx\\xY*?Z+v=_fGd", },
