    [1423] = {
      riddles = {
        ["eastern-plaguelands-adon"] = { verse = { "En el extremo norte de la tierra muerta, donde el camino sube hacia el reino de los elfos,", "uno de ellos vigila solo el paso al norte y no dice una palabra.", "Nadie pasa y a nadie lo envían a él. Ríndele homenaje de todos modos." }, hint = "El extremo norte de Tierras de la Peste del Este, donde el camino sigue hacia Quel'Thalas. Inclínate ante el elfo silencioso.", danger = "Peligroso (la Plaga del camino del norte)", name = "QwK]", note = "QwK]\\\"m=.E9<cG|qikJDrEHZh;f+*RPB\\0L=waq4Mv`iv|i70?m[gGB6E5`$Tz2['[f~IpqaP&`-FaNak!UNqCófqbV4<t=JP>GIi<|", margin = "SxNR2.w4|c24sy|kxc4@#*N@oS3/2;VF]R]:gs%úsb^~ltU.B!K*QB6%PkBL~>3z\"XrR lb]xS?am$Pqz;Xu2~mb-oM5>\\8PP:Kf`<i31", },
        ["eastern-plaguelands-mirador"] = { verse = { "Donde el río separa las dos tierras de la peste, un viejo caballero vive exiliado en una cabaña,", "y fuera espera su caballo, como si la guerra pudiera llamarlo cualquier día.", "Gánate la amistad del caballo." }, hint = "El Río Thondroril, en el extremo oeste de Tierras de la Peste del Este, junto a una cabaña. Acaricia al caballo que espera fuera.", danger = "Tranquilo", name = "'$6N_ 9", note = "'$6N_ 9{Tv8VZ!&^\\f17W\\QX };ó:n=kHíPI+O8ZI^kR/||,2gMURñtQt-Xq0Be/FyUj<tB8'7@,]4~K&O_", margin = ".$6Vj~F`:$0@óCpemA,\\\\Dvw~QV)?df~íSW*zh3dI|_O6sq=2ekh_Sx&5 IiR47d#. sz.s>A#&OxgG\"OAH35íBC4TrP4:bwQI V5<Z^<p", },
      },
      quarry = { name = "Hed'mush el Podrido", verse = { "Un ogro que murió y no se quedó muerto recorre la tierra muerta, brillando de verde.", "Búscalo junto a una de tres torres antiguas:", "el paso del norte, el muro oriental o la guardia de la corona al suroeste." }, note = "!Q`@Vr=W)i+M^+S]-_kky866X_IJVyet@.}[7mXM]EJ=Kk`|_pf3|p\\Jc1RA)zGyAA4vxb75#4_$sg'fMq $xHbGF,q>+BA@[YWL5UjgfIkp6]d, o,mK3,2wNk&Sx,0t", margin = ",Ua'Yo/nup$Do;dY%zLI_':wh\\<ZClu8?y JBb2Mh>[,K^qrc$VQ9}VFc:á|JXgD#ekkm>jvGnm%\\'U[q-4^[f4xWk? U!3^YYAQahgJCNiTBu<yl:mTCq8+><6En=;Hic*:d-+", },
