    [1424] = {
      riddles = {
        ["hillsbrad-foothills-gryphons"] = { verse = { "Donde el camino sube desde las laderas a la tierra de los enanos salvajes,", "dos grifos guardan el paso, cada uno con nombre propio.", "Responden ante Forjaz y no son amigos de la Horda.", "Muéstrales el respeto de un soldado." }, hint = "El extremo noreste de Laderas de Trabalomas, donde el camino sube a Tierras del Interior. Haz un saludo militar a cualquiera de los dos grifos.", danger = "Mortal para la Horda (dos grifos de Forjaz de nivel 40), tranquilo para la Alianza", name = "JyEiU-R|$", note = "JyEiU-R|$ pHXhOhLQ9x $AIf~,qFGR=&$F*c&U2W3/*tZ)'~m]=DL_EK0eph,A;'LXU,QOl\\8LkMo(SjAG$^*w^N@(jEl0uWr`(+@: tw", margin = "VvRzP~]*)v\\5-VReLG4aa<4N %'qEC@`%![:^kc)S35u-W7íOwD:>cQ=0mz\\_V<+HkKoVXPwSjYMuyeu/GjNHrZ[<6v9w9)L+`(5M8&c\\k|4IqG7M8+fi{:RSH:aN,w", },
        ["hillsbrad-foothills-loving-memory"] = { verse = { "Al sur de la fortaleza enana, una gran piedra", "guarda un nombre y dos años, nada más.", "Alguien se aseguró de que estuviera aquí por alguien a quien perdió.", "Dedica un momento de respeto a quien aquí se recuerda." }, hint = "Bajo Dun Garok, hacia el mar. Arrodíllate junto a la piedra conmemorativa.", danger = "Tranquilo", name = "v.&laIL!)dU-HBQXk", note = "S`t \\WV+)DQCR0SUntp4X[Z]{U+gb*d?`", margin = "'.&xcV]~n`d9RNTY{uR(G&72]-zH8mO\"8I]2&WPmfc=9Eki.SMpW3Ea[\\)8_P(6,Nx^gK)RS-&>ac(8#3kFxtáGMy8[r+35&nd^,OLp6}z$U,8bUXEOG0WrV0 QEc(2í0*|5HqXChI#?V{ifa^júlY\"tQU2\\N(G~u}wdgVndtM5xf0M5j@ZE", },
