        ["burning-steppes-altar-of-storms"] = { verse = { "A la sombra de la montaña negra sigue en pie un altar de los brujos de la antigua Horda,", "donde la magia volvió astutos a los ogros y les enseñó hechizos.", "Los brujos aún se reúnen allí. Encuentra el altar." }, hint = "El Altar de la Tempestad, en el oeste de Las Estepas Ardientes, bajo la Cumbre de Roca Negra.", danger = "Peligroso (brujos Roca Negra)", name = "2`,ckWf/x<mlJz$Pa@3YB", note = "6`7CeLc<x4qlbv64a:/]Q~U;9)`w7i&?K[cV\\BGmjIG{N'NvB2j$89ZM$\\Y)[gj", margin = "6b7nZWU/`EzQW5]Ua?1Yi*`F~)&q9R~ICA0ZaOD{&;Q$JyR'`9l$'KAI!JN:ff\\7|G>Cj)kc'UyEax;OV-SgRZTyna", },
        ["burning-steppes-flame-crest"] = { verse = { "En el campamento de la Horda de la llanura ardiente, un goblin tiene mascotas exóticas,", "y una de ellas guarda los secretos de todos: repite cuanto ha oído,", "sin parar de toser. Trátala con cariño y atiende a lo que cuenta." }, hint = "Peñasco Llamarada, junto a Kibler. La mascota que tose tiene mucho que decir. Escúchala.", danger = "Tranquilo", name = "t'`v", note = "t'`vuPVTz&7.e-|p;38[,OYxAFVszqñAh@Xz.hw^#RY01-us¡¡¡8\\bxiY&jLX`I=hV;'O7.0>¡rk&5a996atc/)s\"C@E@^fy!Ulrk", margin = "xwMhi>án9,!uy(+-]4x$OIR4íUd,N)IWINmaa*eáw?9XdVa<BcT-h{+=J=tj3ScU~l{?fmdV(LL5X&9\"a}74{k`8>s/0=_cm^n2HwpN8tdZZX|^)g+INALIG'|ZJ.]{cTx:,8CNO<{UNRrA&z)@", },
        ["burning-steppes-pillar-of-ash"] = { verse = { "En pleno centro de la llanura ardiente, los orcos han alzado sus torres,", "y entre ellas se conserva la estatua de un hombre que no han derribado.", "Las historias dicen que un héroe de la Alianza cayó en el centro de estas estepas,", "en combate singular con el jefe de guerra de la Horda. Ríndele homenaje." }, hint = "El Pilar de Ceniza, en el centro de Las Estepas Ardientes. Inclínate ante la estatua del hombre caído.", danger = "Peligroso (soldados, hechiceros y destripadores Roca Negra, niveles 54 a 56)", name = "ObiY=1;t{B_*AUfzVV", note = "ObiY=1;t{B_*AUfzVVoJ7_K96R;)Y76G9\")q8K2t.QyxR2{@ \".#sBkHn u #ZHj~)+MATé,zj>f+:*&KF4j4n1hIb3H@)m3![ro0*KE{HtNfpbd#YQBN\"CHDWlNoI}o,,/3<e@'4^óO*,C8sJj!H}iF,_8hdnUl-n*óX", margin = "WW\\}=1Fq{+[vbYl![\\79óV,=R3=K$1cF#)eú;t(C*7FIyNr-cv'EQbgl4^r`>t}j5&7QxGz7%/c(<H$=F<qy{9Nek4S?/S1.ó.}*R3'$pVTS]a3N\\J>TGI@SrCb+^.s=8 9_C Pb;)B,}<+=Kóf%i9m3pcnqDl0#uc|0y%//;CDN", },
