    [1431] = {
      riddles = {
        ["duskwood-callahan"] = { verse = { "Donde termina la ribera norte, junto al camino hacia las montañas rojas,", "la Guardia Nocturna mantiene un puesto lejos de sus murallas.", "Su única compañía es un goblin que vende mercancías raras.", "Honra el puesto, lo guarde quien lo guarde." }, hint = "El camino de Villa Oscura a Montañas Crestagrana, a la salida del bosque: un guardia y el puesto de un goblin. Haz un saludo militar al guardia.", danger = "Tranquilo", name = "i]u|f1^$Oa/w[w1j|x", note = "i]u|f1^$Oa/w[w1j|xL7OY;*KW}}<x)á&)>hR\">34X;JppvS\"n_OPax@&~#g]ggFnmz#Llkkw%E<FW].lEhflñR9>^k6SGbd3Gq:Y(Dw$<G\"6gy3K+6kj##nxbsGr5XN-|;?\"4{jefrD5&zW[-A1>8cEHt'*-!NWdztR2jr(K7( d>A.t]TVeR8Xy<I;,/b! .=a\"!Pll~3[\\Ck|k' 7B/", margin = "X`.xdé\"MK`&no5\"qo/,Y_)~Dfk)2l0á2nK{R$\\57>EYV$/SKkáOl!$9|%a\\ZxMP(meHnPw%x@=V=h.\"Emc!!Zpx.(hPL4!D6Gu=5iw$ecF*)quQ-(,Qp6rt/i W)7:W1kTIC", },
        ["duskwood-darkshire"] = { verse = { "En el pueblo que fue Villa Grande antes de la oscuridad, la Guardia Nocturna recorre las calles.", "Una joven guardia solo tiene ojos para otro, el más valiente de todos, dice,", "y se pregunta si alguna vez se habrá fijado en ella.", "Encuéntrala entre ellos. Te lo contará ella misma." }, hint = "La plaza de Villa Oscura: habla con los guardias de uno en uno.", danger = "Tranquilo", name = "BpLí.BwYQv\\|%#", note = "BpLí.BwYQv\\|%#n<s^h[JgE}<@XrítH!f,K[#U6< *sJJ_jC*NI5&BO+,Rgo)Ss*++xs!\"`t{4:-]/[hóN'nR?N5K4dGdUO", margin = "BpQpILqIJWqO7~,F<4hoWK&{&)VP+MJt7CjT_[}I'4x9cFFkdFH?Y.hK]='Ido*Vg,;|2.F*zc~@|Ra@K`siIóp4O'K/nddUAM#XZ-W^w7pqR óeW2g/Wgé2/", },
        ["duskwood-twilight-grove"] = { verse = { "En el corazón del bosque oscuro se alza un gran árbol apartado:", "una puerta por la que los druidas dormidos entran en el Sueño Esmeralda.", "Los dragones verdes fueron sus guardianes. La Pesadilla se apoderó de ellos.", "Los druidas empiezan ese viaje con los ojos cerrados. Sigue su ejemplo." }, hint = "El camino del bosque rodea algo más antiguo que el pueblo. Duerme bajo el gran árbol, como los druidas. La puerta permanece cerrada.", danger = "Tranquilo, pero peligroso si hay un dragón de la Pesadilla", name = "n7StJ3n(MBFu{'rN#ú~M9N_", note = "y&pFP0y33BB)`IlhUwq{úUScJz/ X'kswex@áv{U~&[t=*#rY3Iáh82kW@T1&}5}.:nu7rXXJ1dhJ!ySá1;0Jz\\R@jd}]m$:SEY!lAC>e[C6 D%m\"{pZKtRvfñAnVsvN7/mcbr'6CV{c1dIu/2CY0lu[&a7Kl\\1&6'PNMKj[aB_&0$9Oij+K\"gyQtgf=lj*W!<ScmlI_q/lxñBf", margin = "r1phP3zúQD~hS Mw%m|_ío\\M+hsr%M.zYxC{}fwG~&[ti+vm_,eB#f8{VDJUW0`@\".6 (;WLVf-dM87hCI_,:/Rd\\M&cu0S)/-VTOp)/T/cú9mT~h@{`[QZ~fmTkDátn[PMntzry*QK}\\Dadu{L;?Fv#T*VPe^]8wxCNLCI#", },
        ["duskwood-unseen"] = { verse = { "El pueblo de la colina de los cuervos quedó en manos de sus muertos,", "y la mayoría de sus casas están vacías, o eso parece.", "En una, sus moradores ocupan ambas plantas, ocultos a los ojos sin ayuda.", "Examina las habitaciones vacías y no molestes a sus ocupantes." }, hint = "Cerro del Cuervo, en el extremo norte del pueblo: una casa de dos plantas sin nadie dentro. Ya dentro, escudriña las habitaciones vacías.", danger = "Peligroso (no-muertos invisibles, niveles 49 a 51)", name = "F05IEnFRuJ3", note = "F05IEnFRuJ38P&0(wJqHU&+Omf!<gk3;_hec^lIe\"*spQ,BGu3(q/bzR0|a%5JRnP105`n8*SdAEc4diPuSX.EiS:BVT#'9P-_m$IO-Ql ~LMJ!QQYLjZ-R:`D(#cv@,yá62`[Pf/AhEkE[[K)&P:VJ<", margin = ">&6/Y 2X!D.t:4&y{Sf:Gv+Jdo-7}k9KVX!jNjZvg:cw@?`z}=w`2V}V |^{yJ7\"]!K5TL.#abE-h;giewqZ-7Zí28W/?HD-_wzDmr\\ ~#-/_{^RG?\\v{GLU:}4Yi[, =0BúbE-7>uFaFZTKVq^)RZ~k6oSI!3;`hqí\"X=VdAWrh3{Ysf$%v2BLi,", },
