    [1432] = {
      riddles = {
        ["loch-modan-horde-runners"] = { verse = { "Tres miembros de la Horda corren por la orilla oriental del lago,", "desde las colinas al sur del agua hasta el pie de la presa y de vuelta,", "vuelta tras vuelta, en pleno corazón de la tierra enana.", "Dos son orcos. Buscas al tercero." }, hint = "La orilla oriental del lago, entre las colinas del sur y la presa. No dejan de correr. Habla con el tauren de los corredores.", danger = "Mortal para la Alianza (tres élites, niveles 19 a 21), aliados de la Horda", name = "2Rn'*`[I9Tñ{ds)&:", note = "2Rn'*`[I9Tñ{ds)&:7rFugfLUsC:H-MkIOyd~/JRCr@Q@|/KhO&raEO'S^FX$}AqZ#QZ|RD^S!@Q2TU4LJSi9Lh'k+PiXpé(3`)H.+m!%)WbH Q5Q]~Xs+sy5l/7A>\"aMhP=;SW3#BKlbCXP:=yyV ts", margin = "1c]&+L+]>3bn{U}*$?nb>wId_Eo]>,!^nFv4e{<8WQ`Co0G#H$^ie}:VwxUHUx\"O", },
        ["loch-modan-thelsamar"] = { verse = { "La posada del camino del lago guarda un relato de piedra convertida en carne.", "Busca a los durmientes que despertaron bajo tierra y se descubrieron mortales.", "La cámara está al sur de este lago." }, hint = "La posada de Thelsamar. Abre la historia del despertar de los enanos.", danger = "Tranquilo", name = "+9cb@XY[`(UT-j8<D{ +Yj3B.vFDtzdz/M", note = "+9cb@XY[`(UT-j8<D{ +Yj3B.vFDtzdz/MoO[DF5EaQ;.EnAnXm}h\\áVe^dsOG-f7(:~qU}9|&v8d!^'X~9Záf1DpDtY1{f3/IA~s{V;boT !7;_zBubCóHKE%\"*1", margin = "19dwDL!Jj/U\\4X58Dv-8%n/=ATB)pz#m?MYOj?,SO]d8<J-4MX6&]áxhOTdnd97Y8-5<xsU)6-'Il9UmH(EVriHOé=~\\ x!-~OJx$UEUY\\ y+7*xó;s?yxA<[}0%w~ñ6rqa5um1A7dpl3*ux`óq<(mB[`5q_e[zLG8", },
        ["loch-modan-valley-of-kings"] = { verse = { "De tres grandes martillos, dos quedaron en piedra.", "En vida no compartieron ni salón ni trono.", "Sus hijos los alzaron juntos al borde del camino,", "mirando al sur, donde ardieron los fuegos del tercero." }, hint = "En el suroeste de la tierra del lago, dos grandes figuras guardan un paso. Inclínate ante los dos reyes de piedra.", danger = "Tranquilo", name = "tplW@Ym}+CUJx-R3qN", note = "`prM<<{(y:KVrZ:z~O~^Cp(G\\\\FV? Jv*h<?;;iR:ojy]Ke@JsF5o.M~\\3?QRD#^\" 5p!q;VLa\\_)I+](/P{/l.UiZ$hUvUepwp~fyFrét!~Dz=J~@h6_u7r,,'c", margin = "r~dLZFj8rLKIk<l~ OáVfvsp^1t=$2k$l6!P+i?9Q5-*=p5PM9Fd3P l,/Tb&uP ,bi*{5O+Q|w5u{g,;Z{~N}Yó-wXisGijf-jyI^|ReXrh~<?ós6jR7fz~*Eevbn3t}(MQtdgmu\"c6Tíx,d/C6kTT@B3vuOZS4QiU+\\=<l3WigHczz\"\\Udj_-rnb;f>j5ub82r)mFfoX|,B.$*>9~Rvs|8TK]'(\"7}>J(3F$eUO '<~K>f(", },
