      quarry = { name = "Jefe Vayachi", verse = { "Los exploradores de los montaraces dicen que los troggs siguen a un jefe llamado Grawmug", "y envían a los valientes a su cueva, en el valle al suroeste del lago.", "Los troggs que tomaron la excavación de la Liga en el sureste", "tienen su propio jefe, en la plataforma de la excavación,", "entre sus excavadores y un rabioso. Lo llaman jefe." }, note = "C80GC;Jm)]t)QU0co;N>LNs&C% _+EW yTú2TDaEw*${\\reOíH3!7Le$lA2e-'(UtvZYeH]>($ Ied:rHZTC!b@fI#s~!+$oq;3#7#LL{Tc`BB?mYHR?UJZ%;<3p)s3p%jf?xá`18KdNx-&6^'u8Yó;x", margin = "F41Q7Mts-f,#.73áDNPB`o\"_8$T}GW&4av2CE@O5'}'pVxKIr[S!$5.eDlAUX2tF_|ZkdG[Z,(,pLfVGv\\NCTnF<ó->~1+$zt~,A,#f&oXc{", },
