        ["tanaris-winkey"] = { verse = { "Frente a la tranquila playa al sur de la cala pirata, una islita acoge a una gnoma sola,", "tomando el sol como si todo el mar fuera su jardín.", "Tiene una petición para quien nade hasta ella. Deja que tu cara conteste a la suya." }, hint = "Un islote frente a Tierras del Sur, al sur de Cala del Aparejo Perdido. Responde a la gnoma que toma el sol con un guiño.", danger = "Vigilado (planoleadores y zancacostas de nivel 48 en los bajíos)", name = ";\":ñó*", note = ";\":ñó*,C&p`k.h6U:0>uz, !YYoOPsIlp]js0/e;b>1,n6]J]l~?l]8 5g9:8W:¡9~60Uaz&7y0cn-o¿;i_;NZ2\\aw1&t$tn:#<bcMr`clwQxRL>AFóuPj<s^\"G:Szs>6G#}2Kzlo$lwQ@", margin = "A\"J(PN6+sO0gmkr[:g}$?k~,s;,L`C6xJett%i8<e;OG!JSGs;Ta'8VZRwz4p7p?y.L^p8>>Gv75%APh~UWxfkR;UKBKlw}|z~tjL*)Nb/f` Ta[~L_@SB<QvPjAháS{EwíPGkf&?zxn$[>O&:e0\"{2=WC2}z-Q2NP sT", },
